import { MigrationInterface, QueryRunner } from 'typeorm';

/**
 * `accounting`-tagged (ADR-025). F01 Financial Foundation gap, surfaced by
 * the ADR-048 (Procurement) E2E verification gate: no migration ever
 * seeded a default base/functional currency, so a fresh installation (or
 * one where `accounting_currencies` was ever emptied by direct DB
 * manipulation outside the application — confirmed via `audit_records`
 * for this dev database: real `accounting.currency.created`/
 * `base_changed` events exist from 2026-09-10, the table is empty now,
 * and no application code path can ever delete a currency row) has NO
 * legitimate way to reach a working state again — `createCurrency` can't
 * recreate an existing code (PK conflict) and, before the companion
 * `CurrencyService.setBaseCurrency` correctness fix landed alongside this
 * migration, `setBaseCurrency` refused to designate a first-ever base
 * currency once ANY fiscal year existed, even though nothing was ever
 * posted against a real base currency for that fiscal year to invalidate.
 *
 * Idempotent both ways: inserts EGP only if it doesn't already exist
 * (`ON CONFLICT (code) DO NOTHING`), and promotes it to base ONLY if no
 * currency is currently marked base — never demotes an already-configured
 * installation's real choice.
 */
export class SeedDefaultBaseCurrency1789701100000 implements MigrationInterface {
  name = 'SeedDefaultBaseCurrency1789701100000';

  public async up(queryRunner: QueryRunner): Promise<void> {
    await queryRunner.query(`
      INSERT INTO "accounting_currencies" ("code", "name", "symbol", "decimalPlaces", "roundingMode", "isActive", "isBaseCurrency")
      VALUES ('EGP', 'Egyptian Pound', 'E£', 2, 'half_up', true, NOT EXISTS (SELECT 1 FROM "accounting_currencies" WHERE "isBaseCurrency" = true))
      ON CONFLICT (code) DO NOTHING
    `);
    await queryRunner.query(`
      UPDATE "accounting_currencies" SET "isBaseCurrency" = true
      WHERE "code" = 'EGP' AND NOT EXISTS (SELECT 1 FROM "accounting_currencies" WHERE "isBaseCurrency" = true)
    `);
  }

  public async down(queryRunner: QueryRunner): Promise<void> {
    // Deliberately a no-op: reversing "which currency is base" is exactly the destructive,
    // history-invalidating action this migration exists to make safe to configure in the first
    // place — never undo it automatically. An operator who genuinely needs to change it uses
    // `POST /accounting/currencies/:code/set-base` (now correctly scoped to real changes only).
  }
}

import { ConflictException, Inject, Injectable, NotFoundException, Optional } from '@nestjs/common';
import { utcBusinessDate } from '../../../foundation/localization/business-date';
import { DataSource, EntityManager } from 'typeorm';
import { ApReconciliationRun } from '../infrastructure/ap-reconciliation-run.entity';
import { GLAccount } from '../infrastructure/gl-account.entity';
import { LedgerService } from './ledger.service';
import { AuditService } from '../../../foundation/audit/audit.service';
import { SUPPLIER_LEDGER_CONTRACT, SupplierLedgerContract } from '../../../foundation/module-registry/contracts/ap-events.contract';

export interface ApReconcileInput {
  fiscalPeriodId?: string | null;
  asOfDate?: string;
  orgUnitId?: string | null;
}

/**
 * F05 — Accounts Payable (ADR-037 D2, Blueprint §8). AP↔GL reconciliation.
 * The mirror of `ArReconciliationService`, **guarded/inactive** until a
 * `SUPPLIER_LEDGER_CONTRACT` implementation is provided by the future
 * OP-AP domain:
 *   - contract UNBOUND (today): every run records `no_subledger_source`
 *     and the GL side (the `ap` control account balance) only — NEVER
 *     `matched` (CTO decision, ADR-037 D4);
 *   - contract BOUND (future): identical to `ArReconciliationService` —
 *     Σ supplier balances (via the contract, never a raw table read) vs
 *     the `ap` GL balance, `matched | drift_found`.
 *
 * Read-only — it never posts a correcting entry. All arithmetic SQL
 * `NUMERIC` (ADR-035 D4).
 */
@Injectable()
export class ApReconciliationService {
  constructor(
    private readonly dataSource: DataSource,
    private readonly ledger: LedgerService,
    private readonly audit: AuditService,
    @Optional() @Inject(SUPPLIER_LEDGER_CONTRACT) private readonly supplierLedger?: SupplierLedgerContract,
  ) {}

  private em(manager?: EntityManager): EntityManager {
    return manager ?? this.dataSource.manager;
  }

  async listRuns(filter?: { status?: string; from?: string; to?: string }, manager?: EntityManager): Promise<ApReconciliationRun[]> {
    const qb = this.em(manager).getRepository(ApReconciliationRun).createQueryBuilder('r');
    if (filter?.status) qb.andWhere('r.status = :s', { s: filter.status });
    if (filter?.from) qb.andWhere('r."asOfDate" >= :f', { f: filter.from });
    if (filter?.to) qb.andWhere('r."asOfDate" <= :t', { t: filter.to });
    return qb.orderBy('r."createdAt"', 'DESC').getMany();
  }

  async getRun(id: string, manager?: EntityManager): Promise<ApReconciliationRun> {
    const run = await this.em(manager).getRepository(ApReconciliationRun).findOne({ where: { id } });
    if (!run) throw new NotFoundException(`AP reconciliation run "${id}" not found.`);
    return run;
  }

  private async apAccount(manager?: EntityManager): Promise<GLAccount> {
    const acc = await this.em(manager).getRepository(GLAccount).findOne({ where: { controlFunction: 'ap', isActive: true } });
    if (!acc) throw new ConflictException('No active `ap` control account in the chart of accounts — assign controlFunction "ap" to an account first.');
    return acc;
  }

  async reconcile(input: ApReconcileInput, actorUserId: string, manager?: EntityManager): Promise<ApReconciliationRun> {
    const asOfDate = input.asOfDate ?? utcBusinessDate();
    const ap = await this.apAccount(manager);

    // GL side — always computed
    const gl = await this.ledger.getAccountLedger(ap.id, { to: asOfDate, orgUnitId: input.orgUnitId ?? undefined }, manager);
    const glBalanceBase = gl.closingBalanceBase;

    const repo = this.em(manager).getRepository(ApReconciliationRun);

    // --- No supplier-ledger source (ADR-037 D2/D4) --------------------------
    if (!this.supplierLedger) {
      const saved = await this.save(repo, {
        input,
        asOfDate,
        subledgerTotalBase: null,
        glBalanceBase,
        driftBase: null,
        status: 'no_subledger_source',
        driftBreakdown: {
          note:
            'No operational supplier-ledger source is registered (SUPPLIER_LEDGER_CONTRACT unbound). ' +
            'AP reconciliation activates when the operational supplier-finance (OP-AP) phase provides it. ' +
            'The GL side (the `ap` control account balance) is shown for reference only — this is NOT a match.',
          glClosingBalanceBase: glBalanceBase,
          glLineCount: gl.lines.length,
        },
        actorUserId,
      }, manager);
      await this.recordAudit(actorUserId, saved, { asOfDate, glBalanceBase, status: 'no_subledger_source' }, manager);
      return saved;
    }

    // --- Supplier-ledger source present (future OP-AP) --------------------
    const sub = await this.supplierLedger.getAllSupplierBalances(asOfDate, manager);
    const subledgerTotalBase = sub.total;
    // BUG FIX (surfaced while building GRNI reconciliation, ADR-057): `getAllSupplierBalances`
    // reports a positive balance when AP is credit-increased (correct — a payable is a credit-normal
    // liability), but `LedgerService.getAccountLedger.closingBalanceBase` is UNCONDITIONALLY
    // `Σdebit − Σcredit`, which is NEGATIVE for a normal, matched credit-normal balance. Comparing
    // the two directly without normalizing by the account's own `normalBalance` manufactured a
    // permanent, ~2x-magnitude phantom drift for any non-zero AP balance — masked until now only
    // because earlier checks this session happened to run while AP's net balance was near zero.
    // AR/Cash-Bank/Inventory are unaffected (debit-normal, their subledger conventions already
    // align with `closingBalanceBase`'s sign) — this fix is scoped to credit-normal accounts only.
    const sign = gl.account.normalBalance === 'credit' ? '-1' : '1';
    const [d] = (await this.em(manager).query(
      `SELECT ($1::numeric(20,4) - ($2::numeric(20,4) * $3::numeric(20,4)))::numeric(20,4) AS drift`,
      [subledgerTotalBase, glBalanceBase, sign],
    )) as Array<{ drift: string }>;
    const driftBase = d.drift;
    const matched = Number(driftBase) === 0;

    let driftBreakdown: Record<string, unknown> | null = null;
    if (!matched) {
      driftBreakdown = {
        note: 'Supplier subledger and GL differ. Common causes: an AP FinancialEvent REJECTED by the handler (never posted); a currency mismatch; a manual journal on the ap account (blocked — allowManualJournal=false).',
        subledgerSupplierCount: sub.balances.length,
        subledgerBalances: sub.balances.slice(0, 200),
        glClosingBalanceBase: glBalanceBase,
        glLineCount: gl.lines.length,
      };
    }

    const saved = await this.save(repo, {
      input,
      asOfDate,
      subledgerTotalBase,
      glBalanceBase,
      driftBase,
      status: matched ? 'matched' : 'drift_found',
      driftBreakdown,
      actorUserId,
    }, manager);
    await this.recordAudit(actorUserId, saved, { asOfDate, subledgerTotalBase, glBalanceBase, driftBase, status: saved.status }, manager);
    return saved;
  }

  async closeRun(id: string, actorUserId: string, manager?: EntityManager): Promise<ApReconciliationRun> {
    const run = await this.getRun(id, manager);
    if (run.status === 'closed') return run;
    run.status = 'closed';
    run.closedAt = new Date();
    const saved = await this.em(manager).getRepository(ApReconciliationRun).save(run);
    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'accounting.ap.reconciliation_closed',
      resource: 'ap_reconciliation_run',
      resourceId: id,
      result: 'success',
      correlationId: null,
    }, manager);
    return saved;
  }

  /**
   * F05's accounting AP-position statement. V1: the `ap` control-account
   * GL movement (the AP position). The supplier-level subledger statement
   * activates with the OP-AP phase.
   */
  async apStatement(filter?: { from?: string; to?: string; orgUnitId?: string | null }, manager?: EntityManager): Promise<{
    apAccountCode: string;
    ledger: unknown;
    supplierSubledger: unknown[] | null;
  }> {
    const ap = await this.apAccount(manager);
    const ledger = await this.ledger.getAccountLedger(ap.id, {
      from: filter?.from,
      to: filter?.to,
      orgUnitId: filter?.orgUnitId ?? undefined,
    }, manager);
    return { apAccountCode: ap.code, ledger, supplierSubledger: null };
  }

  // ---------------------------------------------------------------------------

  private async save(
    repo: ReturnType<DataSource['getRepository']>,
    r: {
      input: ApReconcileInput;
      asOfDate: string;
      subledgerTotalBase: string | null;
      glBalanceBase: string;
      driftBase: string | null;
      status: ApReconciliationRun['status'];
      driftBreakdown: Record<string, unknown> | null;
      actorUserId: string;
    }, manager?: EntityManager): Promise<ApReconciliationRun> {
    try {
      return (await repo.save(
        repo.create({
          fiscalPeriodId: r.input.fiscalPeriodId ?? null,
          asOfDate: r.asOfDate,
          orgUnitId: r.input.orgUnitId ?? null,
          subledgerTotalBase: r.subledgerTotalBase,
          glBalanceBase: r.glBalanceBase,
          driftBase: r.driftBase,
          status: r.status,
          driftBreakdown: r.driftBreakdown,
          runByUserId: r.actorUserId,
          closedAt: null,
        }),
      )) as ApReconciliationRun;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      if (/one_open/i.test(msg) || /duplicate key value/i.test(msg)) {
        throw new ConflictException('An open AP reconciliation run already exists for this period/org scope — close it first.');
      }
      throw err;
    }
  }

  private async recordAudit(actorUserId: string, saved: ApReconciliationRun, after: Record<string, unknown>, manager?: EntityManager): Promise<void> {
    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'accounting.ap.reconciliation_run',
      resource: 'ap_reconciliation_run',
      resourceId: saved.id,
      result: 'success',
      correlationId: null,
      after,
    }, manager);
  }
}

import { BadRequestException, ConflictException, Injectable, OnModuleInit, Optional } from '@nestjs/common';
import { DataSource, EntityManager } from 'typeorm';
import {
  CASH_BANK_ADJUSTMENT_META,
  CASH_BANK_ADJUSTMENT_POSTING,
  CASH_BANK_APPROVAL_REQUEST_TYPES,
  CASH_BANK_APPROVER_PERMISSION_NODE,
  CashBankAdjustmentKind,
  isCashBankAdjustmentKind,
} from '../domain/cash-bank';
import { GLAccount } from '../infrastructure/gl-account.entity';
import { FinancialEventService } from './financial-events/financial-event.service';
import { FinancialEventHandlerRegistry } from './financial-events/handler-registry';
import { handleCashBankAdjustmentApproved } from './financial-events/cash-bank-adjustment.handler';
import { AuditService } from '../../../foundation/audit/audit.service';
import { EventBusService } from '../../../foundation/events/event-bus.service';
import { ApprovalEngineService } from '../../../foundation/approval-engine/approval-engine.service';
import { ConfigurationEngineService } from '../../../foundation/configuration-engine/configuration-engine.service';
import { FINANCE_TREASURY_CONTRACT, FinanceTreasuryContract } from '../../../foundation/module-registry/contracts/finance.contract';
import { CASH_BANK_ADJUSTMENT_APPROVED_EVENT } from '../../../foundation/module-registry/contracts/treasury-events.contract';
import { Inject } from '@nestjs/common';
import { isPositiveAmount } from '../domain/money';

const SYSTEM_ACTOR = '00000000-0000-0000-0000-000000000000';
const CLEARING_ACCOUNT_KEY = 'accounting.cash_movement_clearing_account_code';
const OPENING_BALANCE_KEY = 'accounting.cash_bank_opening_balance_account_code';
const THRESHOLD_KEY = 'accounting.cash_bank_adjustment_approval_threshold';

export interface SubmitCashBankAdjustmentInput {
  /** the Treasury account this adjustment concerns (for the approval resource + audit). */
  treasuryAccountId?: string | null;
  /** explicit target `bank` GL account code when the chart has more than one (the handler never guesses). */
  glAccountCode?: string | null;
  kind: CashBankAdjustmentKind;
  amount: string;
  reason: string;
  /** 'debit' | 'credit' — the primary (`bank`, or for reclassification the clearing) account movement. */
  direction?: 'debit' | 'credit';
  /** required for `bank_adjustment` / `unreconciled_write_off`. */
  counterAccountCode?: string | null;
  /** required for `reclassification`. */
  contraAccountCode?: string | null;
  businessDate?: string;
  orgUnitId?: string | null;
}

/**
 * F06 — Cash & Bank (ADR-038 D3/D5). Maker-checker for cash/bank
 * adjustments, **via FA-01** (no cash-specific approval engine). The
 * mirror of `ap-adjustment.service.ts`, with F04's threshold branch
 * (`bank_adjustment` / `reclassification` are threshold-gated).
 *
 * On approval / straight-through: an internal `FinancialEvent`
 * (`accounting.cash.adjustment.approved`) is ingested → F06's handler →
 * F03's posting gate → the `bank` control account. **No hard-coded
 * account codes** — the clearing/opening accounts come from config with
 * fail-closed validation at submit time; the counter/contra accounts are
 * maker-supplied.
 */
@Injectable()
export class CashBankAdjustmentService implements OnModuleInit {
  constructor(
    private readonly dataSource: DataSource,
    private readonly approvals: ApprovalEngineService,
    private readonly financialEvents: FinancialEventService,
    private readonly registry: FinancialEventHandlerRegistry,
    private readonly events: EventBusService,
    private readonly audit: AuditService,
    private readonly config: ConfigurationEngineService,
    @Optional() @Inject(FINANCE_TREASURY_CONTRACT) private readonly treasury?: FinanceTreasuryContract,
  ) {}

  private em(manager?: EntityManager): EntityManager {
    return manager ?? this.dataSource.manager;
  }

  async onModuleInit(): Promise<void> {
    if (!this.registry.get(CASH_BANK_ADJUSTMENT_APPROVED_EVENT)) {
      this.registry.register(CASH_BANK_ADJUSTMENT_APPROVED_EVENT, handleCashBankAdjustmentApproved);
    }
    for (const [kind, meta] of Object.entries(CASH_BANK_ADJUSTMENT_META)) {
      await this.approvals.registerRequestType(meta.requestTypeCode, `action.cash_${kind}`);
      await this.approvals
        .upsertMatrixRule(
          {
            requestTypeCode: meta.requestTypeCode,
            minApprovers: meta.minApprovers,
            requiredPermissionNode: CASH_BANK_APPROVER_PERMISSION_NODE,
            valueThreshold: null,
            orgUnitId: null,
          },
          SYSTEM_ACTOR,
        )
        .catch(() => undefined);
    }
    this.events.subscribe(
    'approval.request.approved',
    async (payload, ctx) => {
      await this.onApprovalApproved(payload as Record<string, unknown>, ctx.manager ?? undefined);
    },
    { scope: 'company' },
  );
  }

  // ---------------------------------------------------------------------------
  // Submit (maker)
  // ---------------------------------------------------------------------------

  async submitAdjustment(
    input: SubmitCashBankAdjustmentInput,
    actorUserId: string, manager?: EntityManager): Promise<{ mode: 'approval'; approvalRequestId: string } | { mode: 'straight_through'; financialEventId: string }> {
    if (!isCashBankAdjustmentKind(input.kind)) throw new BadRequestException(`Unknown cash/bank adjustment kind "${input.kind}".`);
    if (!isPositiveAmount(input.amount)) throw new BadRequestException('Amount must be a positive decimal.');
    if (!input.reason?.trim()) throw new BadRequestException('A reason is required.');

    const meta = CASH_BANK_ADJUSTMENT_META[input.kind];
    const posting = CASH_BANK_ADJUSTMENT_POSTING[input.kind];
    const direction = input.direction ?? posting.bankDirection;

    // per-kind account resolution — fail-closed BEFORE any FA-01 request
    let counterAccountCode: string | null = null;
    let contraAccountCode: string | null = null;
    let openingBalanceAccountCode: string | null = null;
    let clearingAccountCode: string | null = null;

    if (input.kind === 'bank_adjustment' || input.kind === 'unreconciled_write_off') {
      if (!input.counterAccountCode?.trim()) {
        throw new BadRequestException(`A "${input.kind}" requires a counterAccountCode.`);
      }
      counterAccountCode = await this.requirePostableNonControlAccount(input.counterAccountCode.trim(), 'counterAccountCode', manager);
    } else if (input.kind === 'reclassification') {
      if (!input.contraAccountCode?.trim()) {
        throw new BadRequestException('A "reclassification" requires a contraAccountCode.');
      }
      contraAccountCode = await this.requirePostableNonControlAccount(input.contraAccountCode.trim(), 'contraAccountCode', manager);
      clearingAccountCode = await this.requireConfiguredAccount(CLEARING_ACCOUNT_KEY, manager);
    } else if (input.kind === 'opening_balance') {
      openingBalanceAccountCode = await this.requireConfiguredAccount(OPENING_BALANCE_KEY, manager);
    }

    // resolve the target `bank` GL account: explicit code wins; else the
    // mapped Treasury account's `glAccountCode` (so a maker who picked a
    // Treasury account never needs to know a chart code); else the handler
    // falls back to the single `bank` control account.
    let glAccountCode = input.glAccountCode?.trim() || null;
    if (!glAccountCode && input.treasuryAccountId && this.treasury) {
      const { balances } = await this.treasury.getAllTreasuryBalances(undefined, manager);
      glAccountCode = balances.find((b) => b.treasuryAccountId === input.treasuryAccountId)?.glAccountCode ?? null;
    }

    const threshold = this.resolveThreshold(manager);
    const gated = meta.alwaysGated || threshold === null || Number(input.amount) > Number(threshold);

    const payload = {
      kind: input.kind,
      glAccountCode,
      amount: input.amount,
      reason: input.reason.trim(),
      direction,
      counterAccountCode,
      contraAccountCode,
      openingBalanceAccountCode,
      clearingAccountCode,
      treasuryAccountId: input.treasuryAccountId ?? null,
      businessDate: input.businessDate ?? new Date().toISOString().slice(0, 10),
      orgUnitId: input.orgUnitId ?? null,
    };

    if (!gated) {
      const financialEventId = await this.performApprovedAdjustment(payload, actorUserId, undefined, manager);
      await this.audit.record({
        actorUserId,
        organizationId: null,
        action: 'accounting.cash.adjustment_straight_through',
        resource: 'cash_bank',
        resourceId: input.treasuryAccountId ?? input.glAccountCode ?? 'cash-bank',
        result: 'success',
        correlationId: null,
        after: { kind: input.kind, amount: input.amount },
      }, manager);
      return { mode: 'straight_through', financialEventId };
    }

    const request = await this.approvals.submit({
      requestTypeCode: meta.requestTypeCode,
      resourceType: 'CashBank',
      resourceId: (input.treasuryAccountId ?? input.glAccountCode ?? 'cash-bank').slice(0, 64),
      requestedAction: input.kind,
      payload,
      makerUserId: actorUserId,
      orgUnitId: input.orgUnitId ?? null,
    }, manager);
    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'accounting.cash.adjustment_submitted',
      resource: 'approval_request',
      resourceId: request.id,
      result: 'success',
      correlationId: input.treasuryAccountId ?? null,
      after: { kind: input.kind, amount: input.amount, requestTypeCode: meta.requestTypeCode },
    }, manager);
    return { mode: 'approval', approvalRequestId: request.id };
  }

  // ---------------------------------------------------------------------------
  // FA-01 approval subscriber
  // ---------------------------------------------------------------------------

  private async onApprovalApproved(payload: Record<string, unknown>, manager?: EntityManager): Promise<void> {
    const requestTypeCode = String(payload.requestTypeCode ?? '');
    if (!Object.values(CASH_BANK_APPROVAL_REQUEST_TYPES).includes(requestTypeCode as never)) return; // not ours
    const inner = (payload.payload ?? {}) as Record<string, unknown>;
    await this.performApprovedAdjustment(inner, SYSTEM_ACTOR, String(payload.approvalRequestId ?? ''), manager);
  }

  private async performApprovedAdjustment(p: Record<string, unknown>, actorUserId: string, approvalRequestId = '', manager?: EntityManager): Promise<string> {
    const kind = String(p.kind) as CashBankAdjustmentKind;
    const treasuryAccountId = p.treasuryAccountId ? String(p.treasuryAccountId) : null;
    const idBase = approvalRequestId || `${treasuryAccountId ?? p.glAccountCode ?? 'cash'}:${kind}:${p.amount}:${p.businessDate}`;

    const result = await this.financialEvents.ingest(CASH_BANK_ADJUSTMENT_APPROVED_EVENT, {
      idempotencyKey: `accounting:cash_adjustment:${idBase}`,
      businessDate: p.businessDate ?? new Date().toISOString().slice(0, 10),
      orgUnitId: p.orgUnitId ?? null,
      currency: 'EGP',
      sourceEntityType: 'ledger_entry',
      sourceEntityId: (treasuryAccountId ?? String(p.glAccountCode ?? 'cash-bank')).slice(0, 64),
      payloadVersion: 1,
      kind,
      glAccountCode: p.glAccountCode ?? null,
      amount: String(p.amount),
      reason: p.reason ?? '',
      direction: p.direction ?? 'debit',
      counterAccountCode: p.counterAccountCode ?? null,
      contraAccountCode: p.contraAccountCode ?? null,
      openingBalanceAccountCode: p.openingBalanceAccountCode ?? null,
      clearingAccountCode: p.clearingAccountCode ?? null,
    }, manager);

    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'accounting.cash.adjustment_posted',
      resource: 'cash_bank',
      resourceId: (treasuryAccountId ?? String(p.glAccountCode ?? 'cash-bank')).slice(0, 64),
      result: result.status === 'POSTED' ? 'success' : 'failure',
      correlationId: approvalRequestId || null,
      after: { kind, amount: String(p.amount), financialEventId: result.financialEventId, status: result.status },
    }, manager);

    if (result.status === 'REJECTED') {
      throw new ConflictException(`Cash/Bank ${kind} GL posting was rejected — see financial event ${result.financialEventId}.`);
    }
    return result.financialEventId;
  }

  // ---------------------------------------------------------------------------
  // Checker
  // ---------------------------------------------------------------------------

  async decide(requestId: string, approverUserId: string, decision: 'approved' | 'rejected', note?: string, manager?: EntityManager): Promise<unknown> {
    return this.approvals.decide(requestId, approverUserId, decision, note ?? null, manager);
  }

  // ---------------------------------------------------------------------------

  /** `''` / non-numeric → null (fail-closed = always gated). */
  private resolveThreshold(manager?: EntityManager): string | null {
    const raw = (this.config.get<string>(THRESHOLD_KEY) ?? '').trim();
    if (!raw) return null;
    const n = Number(raw);
    return Number.isFinite(n) && n >= 0 ? raw : null;
  }

  /** A config-keyed account code — fail-closed: exists + active + postable + no controlFunction. */
  private async requireConfiguredAccount(configKey: string, manager?: EntityManager): Promise<string> {
    const code = (this.config.get<string>(configKey) ?? '').trim();
    if (!code) {
      throw new BadRequestException(`Config "${configKey}" is not set — set it to a postable non-control GL account code before submitting this adjustment.`);
    }
    return this.requirePostableNonControlAccount(code, configKey, manager);
  }

  private async requirePostableNonControlAccount(code: string, label: string, manager?: EntityManager): Promise<string> {
    const acc = await this.em(manager).getRepository(GLAccount).findOne({ where: { code } });
    if (!acc) throw new BadRequestException(`${label}: GL account "${code}" not found.`);
    if (!acc.isActive) throw new BadRequestException(`${label}: GL account "${code}" is inactive.`);
    if (!acc.isPostable) throw new BadRequestException(`${label}: GL account "${code}" is not postable.`);
    if (acc.controlFunction) throw new BadRequestException(`${label}: GL account "${code}" is a control account — not valid here.`);
    return code;
  }
}

import { ConflictException, Inject, Injectable, NotFoundException } from '@nestjs/common';
import { utcBusinessDate } from '../../../foundation/localization/business-date';
import { DataSource, EntityManager } from 'typeorm';
import { CashBankReconciliationRun } from '../infrastructure/cash-bank-reconciliation-run.entity';
import { GLAccount } from '../infrastructure/gl-account.entity';
import { LedgerService } from './ledger.service';
import { AuditService } from '../../../foundation/audit/audit.service';
import { FINANCE_TREASURY_CONTRACT, FinanceTreasuryContract } from '../../../foundation/module-registry/contracts/finance.contract';

export interface CashBankReconcileInput {
  treasuryAccountId?: string;
  fiscalPeriodId?: string | null;
  asOfDate?: string;
  orgUnitId?: string | null;
}

/**
 * F06 — Cash & Bank (ADR-038 D1/D9, Blueprint §8). Cash/Bank↔GL
 * reconciliation, per Treasury account. Reads the Treasury operational
 * ledger via `FINANCE_TREASURY_CONTRACT` (never a raw `treasury_*` table),
 * the GL `bank` balance via `LedgerService`. Drift in SQL `NUMERIC`
 * (ADR-035 D4).
 *
 * **Read-only — it never posts a correcting entry.** `driftBase ≠ 0` is a
 * diagnostic; the correction is an approved FA-01 `bank_adjustment` /
 * `unreconciled_write_off` (see `CashBankAdjustmentService`).
 *
 * Unlike F05, F06's reconciliation is **active from day one** — the
 * Treasury ledger (its subledger source) always exists, so there is no
 * `no_subledger_source` state.
 */
@Injectable()
export class CashBankReconciliationService {
  constructor(
    private readonly dataSource: DataSource,
    private readonly ledger: LedgerService,
    private readonly audit: AuditService,
    @Inject(FINANCE_TREASURY_CONTRACT) private readonly treasury: FinanceTreasuryContract,
  ) {}

  private em(manager?: EntityManager): EntityManager {
    return manager ?? this.dataSource.manager;
  }

  async listRuns(filter?: { treasuryAccountId?: string; status?: string; from?: string; to?: string }, manager?: EntityManager): Promise<CashBankReconciliationRun[]> {
    const qb = this.em(manager).getRepository(CashBankReconciliationRun).createQueryBuilder('r');
    if (filter?.treasuryAccountId) qb.andWhere('r."treasuryAccountId" = :tid', { tid: filter.treasuryAccountId });
    if (filter?.status) qb.andWhere('r.status = :s', { s: filter.status });
    if (filter?.from) qb.andWhere('r."asOfDate" >= :f', { f: filter.from });
    if (filter?.to) qb.andWhere('r."asOfDate" <= :t', { t: filter.to });
    return qb.orderBy('r."createdAt"', 'DESC').getMany();
  }

  async getRun(id: string, manager?: EntityManager): Promise<CashBankReconciliationRun> {
    const run = await this.em(manager).getRepository(CashBankReconciliationRun).findOne({ where: { id } });
    if (!run) throw new NotFoundException(`Cash/Bank reconciliation run "${id}" not found.`);
    return run;
  }

  private async glAccountByCode(code: string, manager?: EntityManager): Promise<GLAccount> {
    const acc = await this.em(manager).getRepository(GLAccount).findOne({ where: { code, isActive: true } });
    if (!acc) {
      throw new ConflictException(`GL account "${code}" (mapped from a Treasury account) is missing or inactive in the chart.`);
    }
    return acc;
  }

  /**
   * Reconcile one Treasury account (or every GL-mapped one when
   * `treasuryAccountId` is omitted). Returns the run(s) it created.
   */
  async reconcile(input: CashBankReconcileInput, actorUserId: string, manager?: EntityManager): Promise<CashBankReconciliationRun[]> {
    const asOfDate = input.asOfDate ?? utcBusinessDate();
    const { balances } = await this.treasury.getAllTreasuryBalances(asOfDate, manager);

    let targets = balances.filter((b) => b.glAccountCode && b.glAccountCode.trim() !== '');
    if (input.treasuryAccountId) {
      targets = targets.filter((b) => b.treasuryAccountId === input.treasuryAccountId);
      if (targets.length === 0) {
        const known = balances.find((b) => b.treasuryAccountId === input.treasuryAccountId);
        if (!known) throw new NotFoundException(`Treasury account "${input.treasuryAccountId}" not found.`);
        throw new ConflictException(`Treasury account "${known.code}" is not GL-mapped — set its glAccountCode before reconciling.`);
      }
    }
    if (targets.length === 0) {
      throw new ConflictException('No GL-mapped Treasury account to reconcile — set glAccountCode on at least one account.');
    }

    const repo = this.em(manager).getRepository(CashBankReconciliationRun);
    const runs: CashBankReconciliationRun[] = [];

    for (const b of targets) {
      const glCode = b.glAccountCode!;
      const gl = await this.glAccountByCode(glCode, manager);
      const glLedger = await this.ledger.getAccountLedger(gl.id, { to: asOfDate, orgUnitId: input.orgUnitId ?? undefined }, manager);
      const glBalanceBase = glLedger.closingBalanceBase;
      const subledgerTotalBase = b.balance;

      const [d] = (await this.em(manager).query(`SELECT ($1::numeric(20,4) - $2::numeric(20,4))::numeric(20,4) AS drift`, [
        subledgerTotalBase,
        glBalanceBase,
      ])) as Array<{ drift: string }>;
      const driftBase = d.drift;
      const matched = Number(driftBase) === 0;

      const driftBreakdown: Record<string, unknown> | null = matched
        ? null
        : {
            note:
              'The Treasury operational ledger and the GL `bank` account differ. Common causes: an un-GL-mapped movement on a sibling account; a Treasury movement whose GL event was REJECTED (see Financial Events); a deposit/COD cash leg not yet posted to GL (owned by F09); a bank charge/fee not yet recorded; a manual journal on the `bank` account (blocked — allowManualJournal=false).',
            treasuryAccountId: b.treasuryAccountId,
            treasuryAccountCode: b.code,
            glAccountCode: glCode,
            treasuryLedgerTotalBase: subledgerTotalBase,
            glClosingBalanceBase: glBalanceBase,
            glLineCount: glLedger.lines.length,
          };

      const saved = await this.save(repo, {
        input,
        treasuryAccountId: b.treasuryAccountId,
        glAccountCode: glCode,
        asOfDate,
        subledgerTotalBase,
        glBalanceBase,
        driftBase,
        status: matched ? 'matched' : 'drift_found',
        driftBreakdown,
        actorUserId,
      }, manager);
      await this.audit.record({
        actorUserId,
        organizationId: null,
        action: 'accounting.cash.reconciliation_run',
        resource: 'cash_bank_reconciliation_run',
        resourceId: saved.id,
        result: 'success',
        correlationId: null,
        after: { treasuryAccountId: b.treasuryAccountId, glAccountCode: glCode, asOfDate, subledgerTotalBase, glBalanceBase, driftBase, status: saved.status },
      }, manager);
      runs.push(saved);
    }
    return runs;
  }

  async closeRun(id: string, actorUserId: string, manager?: EntityManager): Promise<CashBankReconciliationRun> {
    const run = await this.getRun(id, manager);
    if (run.status === 'closed') return run;
    run.status = 'closed';
    run.closedAt = new Date();
    const saved = await this.em(manager).getRepository(CashBankReconciliationRun).save(run);
    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'accounting.cash.reconciliation_closed',
      resource: 'cash_bank_reconciliation_run',
      resourceId: id,
      result: 'success',
      correlationId: null,
    }, manager);
    return saved;
  }

  /**
   * A per-GL-account roll-up of the latest run per Treasury account
   * (ADR-038 D9) — several Treasury accounts may map to one GL account.
   */
  async rollup(manager?: EntityManager): Promise<Array<{ glAccountCode: string; treasuryLedgerTotalBase: string; glBalanceBase: string; driftBase: string; accountCount: number }>> {
    const rows = (await this.em(manager).query(
      `WITH latest AS (
         SELECT DISTINCT ON ("treasuryAccountId") "treasuryAccountId", "glAccountCode", "subledgerTotalBase", "glBalanceBase"
           FROM "accounting_cash_bank_reconciliation_runs"
          ORDER BY "treasuryAccountId", "createdAt" DESC
       )
       SELECT "glAccountCode",
              SUM("subledgerTotalBase")::numeric(20,4) AS "treasuryLedgerTotalBase",
              MAX("glBalanceBase")::numeric(20,4)      AS "glBalanceBase",
              (SUM("subledgerTotalBase") - MAX("glBalanceBase"))::numeric(20,4) AS "driftBase",
              COUNT(*)::int AS "accountCount"
         FROM latest
        GROUP BY "glAccountCode"
        ORDER BY "glAccountCode"`,
    )) as Array<{ glAccountCode: string; treasuryLedgerTotalBase: string; glBalanceBase: string; driftBase: string; accountCount: number }>;
    return rows;
  }

  /**
   * F06's Cash/Bank position statement for one Treasury account: the GL
   * `bank` account movement + the Treasury operational ledger, side by side.
   */
  async cashBankPositionStatement(input: { treasuryAccountId: string; from?: string; to?: string }, manager?: EntityManager): Promise<{
    treasuryAccountId: string;
    glAccountCode: string | null;
    glLedger: unknown | null;
    treasuryLedger: unknown[];
  }> {
    const { balances } = await this.treasury.getAllTreasuryBalances(input.to, manager);
    const acc = balances.find((b) => b.treasuryAccountId === input.treasuryAccountId);
    if (!acc) throw new NotFoundException(`Treasury account "${input.treasuryAccountId}" not found.`);
    const treasuryLedger = await this.treasury.listTreasuryLedger(input.treasuryAccountId, { from: input.from, to: input.to }, manager);
    let glLedger: unknown | null = null;
    if (acc.glAccountCode) {
      const gl = await this.glAccountByCode(acc.glAccountCode, manager);
      glLedger = await this.ledger.getAccountLedger(gl.id, { from: input.from, to: input.to }, manager);
    }
    return { treasuryAccountId: input.treasuryAccountId, glAccountCode: acc.glAccountCode, glLedger, treasuryLedger };
  }

  // ---------------------------------------------------------------------------

  private async save(
    repo: ReturnType<DataSource['getRepository']>,
    r: {
      input: CashBankReconcileInput;
      treasuryAccountId: string;
      glAccountCode: string;
      asOfDate: string;
      subledgerTotalBase: string;
      glBalanceBase: string;
      driftBase: string;
      status: CashBankReconciliationRun['status'];
      driftBreakdown: Record<string, unknown> | null;
      actorUserId: string;
    }, manager?: EntityManager): Promise<CashBankReconciliationRun> {
    try {
      return (await repo.save(
        repo.create({
          treasuryAccountId: r.treasuryAccountId,
          glAccountCode: r.glAccountCode,
          fiscalPeriodId: r.input.fiscalPeriodId ?? null,
          asOfDate: r.asOfDate,
          orgUnitId: r.input.orgUnitId ?? null,
          subledgerTotalBase: r.subledgerTotalBase,
          glBalanceBase: r.glBalanceBase,
          driftBase: r.driftBase,
          status: r.status,
          driftBreakdown: r.driftBreakdown,
          runByUserId: r.actorUserId,
          closedAt: null,
        }),
      )) as CashBankReconciliationRun;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      if (/one_open/i.test(msg) || /duplicate key value/i.test(msg)) {
        throw new ConflictException('An open Cash/Bank reconciliation run already exists for this account/period/org scope — close it first.');
      }
      throw err;
    }
  }
}

import { ConflictException, Inject, Injectable, NotFoundException, Optional } from '@nestjs/common';
import { utcBusinessDate } from '../../../foundation/localization/business-date';
import { DataSource, EntityManager } from 'typeorm';
import { InventoryReconciliationRun } from '../infrastructure/inventory-reconciliation-run.entity';
import { GLAccount } from '../infrastructure/gl-account.entity';
import { LedgerService } from './ledger.service';
import { AuditService } from '../../../foundation/audit/audit.service';
import { INVENTORY_VALUATION_CONTRACT, InventoryValuationContract } from '../../../foundation/module-registry/contracts/inventory-events.contract';
import { MANUFACTURING_WIP_CONTRACT, ManufacturingWipContract } from '../../../foundation/module-registry/contracts/manufacturing-wip.contract';

export interface InventoryReconcileInput {
  fiscalPeriodId?: string | null;
  asOfDate?: string;
  orgUnitId?: string | null;
}

/**
 * F07 — Inventory Accounting (ADR-040 D10, CTO Mandatory Condition E).
 * Inventory↔GL reconciliation. The mirror of `ApReconciliationService`,
 * **guarded/inactive** until an `InventoryValuationContract` implementation
 * is provided by the future F08 (Inventory Valuation) phase:
 *   - contract UNBOUND (today): every run records `no_valuation_source`
 *     and shows the GL side (the `inventory` control account balance) for
 *     reference only — **NEVER `matched`**;
 *   - contract BOUND (future F08): identical to `ApReconciliationService`'s
 *     bound branch — Σ valued on-hand (via the contract, never a raw table
 *     read) vs the `inventory` GL balance, `matched | drift_found`.
 *
 * Read-only — it never posts a correcting entry. All arithmetic SQL
 * `NUMERIC` (ADR-035 D4). No auto-correction, ever.
 */
@Injectable()
export class InventoryReconciliationService {
  constructor(
    private readonly dataSource: DataSource,
    private readonly ledger: LedgerService,
    private readonly audit: AuditService,
    @Optional() @Inject(INVENTORY_VALUATION_CONTRACT) private readonly valuation?: InventoryValuationContract,
    // Month-End dependency (independent review, Phase 1) — when Manufacturing is installed, every
    // Work Order's dedicated WIP sub-warehouse (ADR-061 §6) is EXCLUDED from this service's own
    // subledger sum below: its value has already been reclassified out of the `inventory` GL
    // control account into `wip` (Dr WIP / Cr Inventory), so it belongs to `WipReconciliationService`'s
    // own comparison against the `wip` account, never this one's. `@Optional()` — when Manufacturing
    // is not installed, `valued` is used exactly as before, unchanged (Case F: no behavior change for
    // any non-Manufacturing installation).
    @Optional() @Inject(MANUFACTURING_WIP_CONTRACT) private readonly manufacturingWip?: ManufacturingWipContract,
  ) {}

  private em(manager?: EntityManager): EntityManager {
    return manager ?? this.dataSource.manager;
  }

  async listRuns(filter?: { status?: string; from?: string; to?: string }, manager?: EntityManager): Promise<InventoryReconciliationRun[]> {
    const qb = this.em(manager).getRepository(InventoryReconciliationRun).createQueryBuilder('r');
    if (filter?.status) qb.andWhere('r.status = :s', { s: filter.status });
    if (filter?.from) qb.andWhere('r."asOfDate" >= :f', { f: filter.from });
    if (filter?.to) qb.andWhere('r."asOfDate" <= :t', { t: filter.to });
    return qb.orderBy('r."createdAt"', 'DESC').getMany();
  }

  async getRun(id: string, manager?: EntityManager): Promise<InventoryReconciliationRun> {
    const run = await this.em(manager).getRepository(InventoryReconciliationRun).findOne({ where: { id } });
    if (!run) throw new NotFoundException(`Inventory reconciliation run "${id}" not found.`);
    return run;
  }

  private async inventoryAccount(manager?: EntityManager): Promise<GLAccount> {
    const acc = await this.em(manager).getRepository(GLAccount).findOne({ where: { controlFunction: 'inventory', isActive: true } });
    if (!acc) {
      throw new ConflictException('No active `inventory` control account in the chart of accounts — assign controlFunction "inventory" to an account first.');
    }
    return acc;
  }

  async reconcile(input: InventoryReconcileInput, actorUserId: string, manager?: EntityManager): Promise<InventoryReconciliationRun> {
    const asOfDate = input.asOfDate ?? utcBusinessDate();
    const inv = await this.inventoryAccount(manager);

    // GL side — always computed
    const gl = await this.ledger.getAccountLedger(inv.id, { to: asOfDate, orgUnitId: input.orgUnitId ?? undefined }, manager);
    const glBalanceBase = gl.closingBalanceBase;

    const repo = this.em(manager).getRepository(InventoryReconciliationRun);

    // --- No valuation source (ADR-040 D3/D10) --------------------------------
    if (!this.valuation) {
      const saved = await this.save(repo, {
        input,
        asOfDate,
        subledgerTotalBase: null,
        glBalanceBase,
        driftBase: null,
        status: 'no_valuation_source',
        driftBreakdown: {
          note:
            'No inventory valuation source is registered (INVENTORY_VALUATION_CONTRACT unbound). ' +
            'Inventory reconciliation activates when F08 (Inventory Valuation) provides it. ' +
            'The GL side (the `inventory` control account balance) is shown for reference only — this is NOT a match.',
          glClosingBalanceBase: glBalanceBase,
          glLineCount: gl.lines.length,
        },
        actorUserId,
      }, manager);
      await this.recordAudit(actorUserId, saved, { asOfDate, glBalanceBase, status: 'no_valuation_source' }, manager);
      return saved;
    }

    // --- Valuation source present (future F08) -------------------------------
    const rawValued = await this.valuation.getValuedOnHandTotal(asOfDate, manager);
    // Month-End dependency (independent review, Phase 1) — exclude every Manufacturing WIP
    // sub-warehouse from THIS reconciliation's own sum; `WipReconciliationService` covers that
    // slice against the `wip` GL account separately. See the constructor's `manufacturingWip`
    // doc comment for why this must be a split, never a combined/netted comparison.
    let valued = rawValued;
    if (this.manufacturingWip) {
      const wip = await this.manufacturingWip.getAllWipBalances(asOfDate, manager);
      const wipWarehouseIds = new Set(wip.balances.map((b) => b.wipWarehouseId));
      valued = rawValued.filter((w) => !wipWarehouseIds.has(w.warehouseId));
    }
    const subledgerTotalBase = valued.reduce((sum, w) => sum + Number(w.totalValueBase), 0).toFixed(4);
    const [d] = (await this.em(manager).query(`SELECT ($1::numeric(20,4) - $2::numeric(20,4))::numeric(20,4) AS drift`, [
      subledgerTotalBase,
      glBalanceBase,
    ])) as Array<{ drift: string }>;
    const driftBase = d.drift;
    const matched = Number(driftBase) === 0;

    const driftBreakdown: Record<string, unknown> | null = matched
      ? null
      : {
          note:
            'The valued on-hand position and the GL `inventory` account differ. Common causes: a dispatch FinancialEvent REJECTED (never posted); a manual journal on the inventory account (blocked — allowManualJournal=false); a movement type not yet mapped to GL.',
          warehouseBreakdown: valued,
          glClosingBalanceBase: glBalanceBase,
          glLineCount: gl.lines.length,
        };

    const saved = await this.save(repo, {
      input,
      asOfDate,
      subledgerTotalBase,
      glBalanceBase,
      driftBase,
      status: matched ? 'matched' : 'drift_found',
      driftBreakdown,
      actorUserId,
    }, manager);
    await this.recordAudit(actorUserId, saved, { asOfDate, subledgerTotalBase, glBalanceBase, driftBase, status: saved.status }, manager);
    return saved;
  }

  async closeRun(id: string, actorUserId: string, manager?: EntityManager): Promise<InventoryReconciliationRun> {
    const run = await this.getRun(id, manager);
    if (run.status === 'closed') return run;
    run.status = 'closed';
    run.closedAt = new Date();
    const saved = await this.em(manager).getRepository(InventoryReconciliationRun).save(run);
    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'accounting.inventory.reconciliation_closed',
      resource: 'inventory_reconciliation_run',
      resourceId: id,
      result: 'success',
      correlationId: null,
    }, manager);
    return saved;
  }

  // ---------------------------------------------------------------------------

  private async save(
    repo: ReturnType<DataSource['getRepository']>,
    r: {
      input: InventoryReconcileInput;
      asOfDate: string;
      subledgerTotalBase: string | null;
      glBalanceBase: string;
      driftBase: string | null;
      status: InventoryReconciliationRun['status'];
      driftBreakdown: Record<string, unknown> | null;
      actorUserId: string;
    }, manager?: EntityManager): Promise<InventoryReconciliationRun> {
    try {
      return (await repo.save(
        repo.create({
          fiscalPeriodId: r.input.fiscalPeriodId ?? null,
          asOfDate: r.asOfDate,
          orgUnitId: r.input.orgUnitId ?? null,
          subledgerTotalBase: r.subledgerTotalBase,
          glBalanceBase: r.glBalanceBase,
          driftBase: r.driftBase,
          status: r.status,
          driftBreakdown: r.driftBreakdown,
          runByUserId: r.actorUserId,
          closedAt: null,
        }),
      )) as InventoryReconciliationRun;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      if (/one_open/i.test(msg) || /duplicate key value/i.test(msg)) {
        throw new ConflictException('An open Inventory reconciliation run already exists for this period/org scope — close it first.');
      }
      throw err;
    }
  }

  private async recordAudit(actorUserId: string, saved: InventoryReconciliationRun, after: Record<string, unknown>, manager?: EntityManager): Promise<void> {
    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'accounting.inventory.reconciliation_run',
      resource: 'inventory_reconciliation_run',
      resourceId: saved.id,
      result: 'success',
      correlationId: null,
      after,
    }, manager);
  }
}

