/**
 * ADR-070 — Payroll Phase 1 application service. Implements the ratified
 * `ADR-067` decisions exactly: componentized Earnings (§B), independent
 * day-type determination with the `unclassified`/no-deduction fail-safe
 * (§C — Holiday Calendar remains an open `ADR-053 §16` escalation, never
 * invented here), no overtime/tax/insurance computation (§D/§E, both
 * genuinely unresolved, not simulated), and GL posting exclusively
 * through the existing Financial Event architecture (§K).
 */
@Injectable()
export class PayrollService implements OnModuleInit {
  constructor(
    private readonly dataSource: DataSource,
    private readonly audit: AuditService,
    private readonly events: EventBusService,
    private readonly approvals: ApprovalEngineService,
    private readonly processEngine: ProcessEngineService,
    private readonly numbering: NumberingService,
    private readonly hr: HrService,
    private readonly attendance: AttendanceService,
    private readonly commission: CommissionService,
    @Inject(FINANCE_TREASURY_CONTRACT) private readonly treasury: FinanceTreasuryContract,
  ) {}

  private em(manager?: EntityManager): EntityManager {
    return manager ?? this.dataSource.manager;
  }

  /** Area 21: repositories bound to the caller's connection — the Company's own when a Company `manager` is passed, the ambient one otherwise. */
  private repos(manager?: EntityManager) {
    const em = this.em(manager);
    return {
      periods: em.getRepository(PayrollPeriod),
      compensations: em.getRepository(PayrollCompensation),
      earningLines: em.getRepository(PayrollEarningLine),
      runs: em.getRepository(PayrollRun),
      runLines: em.getRepository(PayrollRunLine),
      dayClassifications: em.getRepository(PayrollAttendanceDayClassification),
      deductionLines: em.getRepository(PayrollDeductionLine),
      adjustments: em.getRepository(PayrollAdjustment),
    };
  }

  /** The payroll document types are registered at boot in the ambient DB; a Company's own database gets them on first use (idempotent). */
  private async ensureNumbering(manager?: EntityManager): Promise<void> {
    if (!manager) return;
    await this.numbering.registerDocumentType('payroll_run', 'PR', true, manager);
    await this.numbering.registerDocumentType('payroll_compensation', 'PC', true, manager);
  }

  async onModuleInit(): Promise<void> {
    await this.numbering.registerDocumentType('payroll_run', 'PR', true).catch(() => undefined);
    await this.numbering.registerDocumentType('payroll_compensation', 'PC', true).catch(() => undefined);

    await this.approvals.registerRequestType(APPROVAL_TYPE, 'action.payroll_submit_approval');
    await this.approvals
      .upsertMatrixRule({ requestTypeCode: APPROVAL_TYPE, minApprovers: 1, requiredPermissionNode: APPROVER_NODE, valueThreshold: null, orgUnitId: null }, SYSTEM_ACTOR_ID)
      .catch(() => undefined);

    this.events.subscribe(
    'approval.request.approved',
    async (payload, ctx) => {
      await this.onApprovalApproved(payload as Record<string, unknown>, ctx.manager ?? undefined);
    },
    { scope: 'company' },
  );
  }

  // ---------------------------------------------------------------------------
  // Periods — ADR-070 §A. Monthly in Phase 1; the model itself carries no
  // frequency assumption beyond what the caller supplies.
  // ---------------------------------------------------------------------------

  async createPeriod(input: CreatePeriodInput, actorUserId: string, manager?: EntityManager): Promise<PayrollPeriod> {
    if (input.startDate > input.endDate) throw new ConflictException('startDate must be on or before endDate.');
    const saved = await this.repos(manager).periods.save(this.repos(manager).periods.create({ code: input.code, startDate: input.startDate, endDate: input.endDate, status: 'open' }));
    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'payroll.period.created',
      resource: 'payroll_period',
      resourceId: saved.id,
      result: 'success',
      correlationId: null,
      after: { code: input.code, startDate: input.startDate, endDate: input.endDate },
    }, manager);
    return saved;
  }

  async listPeriods(manager?: EntityManager): Promise<PayrollPeriod[]> {
    return this.repos(manager).periods.find({ order: { startDate: 'DESC' } });
  }

  // ---------------------------------------------------------------------------
  // Compensation — ADR-070 §B. Effective-dated; a change never rewrites a
  // prior period's history. Componentized Earnings, never a single figure.
  // ---------------------------------------------------------------------------

  async createCompensation(input: CreateCompensationInput, actorUserId: string, manager?: EntityManager): Promise<PayrollCompensation> {
    await this.hr.getEmployee(input.employeeId, manager); // throws NotFoundException if the employee does not exist
    if (input.earnings.length === 0) throw new ConflictException('At least one earning line is required.');
    for (const line of input.earnings) {
      if (!(Number(line.amount) > 0)) throw new ConflictException(`Earning line "${line.componentCode}" must have a positive amount.`);
    }

    return this.em(manager).transaction(async (manager) => {
      const existingActive = await manager.getRepository(PayrollCompensation).findOne({ where: { employeeId: input.employeeId, effectiveTo: IsNull() } });
      const now = new Date();
      if (existingActive) {
        existingActive.effectiveTo = now;
        existingActive.status = 'superseded';
        await manager.getRepository(PayrollCompensation).save(existingActive);
      }

      const saved = await manager.getRepository(PayrollCompensation).save(
        manager.getRepository(PayrollCompensation).create({ employeeId: input.employeeId, effectiveFrom: now, effectiveTo: null, status: 'active', createdByUserId: actorUserId }),
      );
      for (const line of input.earnings) {
        await manager.getRepository(PayrollEarningLine).save(manager.getRepository(PayrollEarningLine).create({ compensationId: saved.id, componentCode: line.componentCode, amount: line.amount }));
      }

      await this.audit.record(
        {
          actorUserId,
          organizationId: null,
          action: 'payroll.compensation.created',
          resource: 'payroll_compensation',
          resourceId: saved.id,
          result: 'success',
          correlationId: null,
          after: { employeeId: input.employeeId, earnings: input.earnings },
        },
        manager,
      );
      return saved;
    });
  }

  async listCompensations(employeeId?: string, manager?: EntityManager): Promise<PayrollCompensation[]> {
    return this.repos(manager).compensations.find({ where: employeeId ? { employeeId } : {}, order: { createdAt: 'DESC' } });
  }

  private async getActiveCompensationWithLines(employeeId: string, manager?: EntityManager): Promise<{ compensation: PayrollCompensation; lines: PayrollEarningLine[] } | null> {
    const compensation = await this.repos(manager).compensations.findOne({ where: { employeeId, effectiveTo: IsNull() } });
    if (!compensation) return null;
    const lines = await this.repos(manager).earningLines.find({ where: { compensationId: compensation.id } });
    return { compensation, lines };
  }

  // ---------------------------------------------------------------------------
  // Day-type determination — ADR-070 §9/§C, binding Payroll control, not UI
  // behavior. `AttendanceDay.status = 'absent'` never alone implies a
  // deduction. No `PayrollCalendarPolicy` source exists yet (Holiday
  // Calendar remains an open ADR-053 §16 escalation, ADR-067 §C/ADR-070
  // §21) — every 'absent' day therefore resolves to the fail-safe:
  // `unclassified`/`none`, never `deduction`. This is not a shortcut; it is
  // the documented, correct behavior until that policy is supplied.
  // ---------------------------------------------------------------------------

  classifyDay(attendanceStatus: 'present' | 'absent' | 'on_leave' | 'missing_punch'): { dayType: PayrollDayType; payImpact: PayrollDayPayImpact } {
    switch (attendanceStatus) {
      case 'on_leave':
        return { dayType: 'approved_leave', payImpact: 'none' };
      case 'present':
        return { dayType: 'working', payImpact: 'none' };
      case 'missing_punch':
        // Phase 1: incomplete punch data is a data-quality flag, never an automatic deduction —
        // no policy authorizes deducting pay for a missing punch alone.
        return { dayType: 'working', payImpact: 'none' };
      case 'absent':
        // Fail-safe (ADR-070 §21 escalation): no Holiday Calendar/weekend-pattern source exists
        // yet, so Payroll cannot distinguish a genuine working-day absence from a weekend/holiday.
        // Absence of a calendar answer defaults to "do not deduct," never "assume working day."
        return { dayType: 'unclassified', payImpact: 'none' };
    }
  }

  // ---------------------------------------------------------------------------
  // PayrollRun — ADR-070 §5/§9/§13. calculate() is safe to re-invoke while
  // the run is still 'draft' (idempotent recompute); it is a no-op (in
  // fact, rejected) once the run has left 'draft'.
  // ---------------------------------------------------------------------------

  async calculate(payrollPeriodId: string, actorUserId: string, manager?: EntityManager): Promise<PayrollRun> {
    const period = await this.repos(manager).periods.findOne({ where: { id: payrollPeriodId } });
    if (!period) throw new NotFoundException(`Payroll period "${payrollPeriodId}" not found.`);

    let run = await this.repos(manager).runs.findOne({ where: { payrollPeriodId } });
    let isNew = false;
    if (!run) {
      await this.ensureNumbering(manager);
      const code = await this.numbering.getNextNumber('payroll_run', manager);
      run = await this.repos(manager).runs.save(this.repos(manager).runs.create({ code, payrollPeriodId, status: 'draft', createdByUserId: actorUserId }));
      await this.processEngine.start(PAYROLL_RUN_PROCESS, RUN_ENTITY_TYPE, run.id, manager);
      isNew = true;
    }

    const state = await this.processEngine.getState(PAYROLL_RUN_PROCESS, RUN_ENTITY_TYPE, run.id, manager);
    if (state !== 'draft' && state !== 'calculated') {
      throw new ConflictException(`PayrollRun "${run.id}" is already "${state}" — recalculation requires a new run/period (ADR-070 §18, immutability).`);
    }

    // Idempotent recompute: discard prior draft lines for this still-uncommitted run (ADR-070 §12).
    const existingLines = await this.repos(manager).runLines.find({ where: { payrollRunId: run.id } });
    for (const line of existingLines) {
      await this.repos(manager).dayClassifications.delete({ payrollRunLineId: line.id });
      await this.repos(manager).deductionLines.delete({ payrollRunLineId: line.id });
    }
    if (existingLines.length > 0) await this.repos(manager).runLines.delete({ payrollRunId: run.id });

    // Population scope (ADR-067 §I): active, non-contractor employees only.
    const employees = await this.hr.listEmployees(manager);
    const eligible = employees.filter((e) => e.status === 'active' && e.employmentType !== 'contractor');

    // Attendance facts via the read contract ADR-070 §9 specifies — approved batches overlapping
    // this period's date range, never raw attendance data.
    const batches = await this.attendance.listApprovalBatches(manager);
    const relevantBatches = batches.filter((b) => b.status === 'approved' && b.periodStart <= period.endDate && b.periodEnd >= period.startDate);
    const daysByEmployee = new Map<string, Array<{ calendarDate: string; status: 'present' | 'absent' | 'on_leave' | 'missing_punch' }>>();
    for (const batch of relevantBatches) {
      const days = await this.attendance.listApprovedDaysByBatch(batch.id, manager);
      for (const day of days) {
        const arr = daysByEmployee.get(day.employeeId) ?? [];
        arr.push({ calendarDate: day.calendarDate, status: day.status });
        daysByEmployee.set(day.employeeId, arr);
      }
    }

    const now = new Date();
    for (const emp of eligible) {
      const comp = await this.getActiveCompensationWithLines(emp.id, manager);
      if (!comp) continue; // no active compensation configured — genuinely out of this run's scope, not an error

      const grossPay = comp.lines.reduce((sum, l) => sum + Number(l.amount), 0);
      // No system-derived attendance deduction is ever created in this Phase 1 slice — the
      // classification fail-safe above guarantees payImpact is never 'deduction' until a Holiday
      // Calendar policy exists, so there is no rate/formula to invent here.
      const totalDeductions = 0;

      // ADR-070 §J/ADR-067 §J/ADR-068 §G — Payroll consumes only an APPROVED Commission Result;
      // it never recomputes commission from Sales/Customer data. An unapproved/draft/rejected
      // result is not readable through this contract at all (CommissionService.
      // listApprovedCommissionResults only ever returns batch-approved rows).
      const approvedCommissionResults = await this.commission.listApprovedCommissionResults(emp.id, period.startDate, period.endDate, manager);
      const commissionAmount = approvedCommissionResults.reduce((sum, r) => sum + Number(r.calculatedAmount), 0);

      const netPay = grossPay + commissionAmount - totalDeductions;

      const line = await this.repos(manager).runLines.save(
        this.repos(manager).runLines.create({
          payrollRunId: run.id,
          employeeId: emp.id,
          compensationSnapshot: { compensationId: comp.compensation.id, earnings: comp.lines.map((l) => ({ componentCode: l.componentCode, amount: l.amount })) },
          grossPay: grossPay.toFixed(2),
          totalDeductions: totalDeductions.toFixed(2),
          netPay: netPay.toFixed(2),
          commissionAmount: approvedCommissionResults.length > 0 ? commissionAmount.toFixed(2) : null,
          overtimeAmount: null, // ADR-067 §D — reserved extension point, not computed
          calculationTimestamp: now,
        }),
      );

      const employeeDays = (daysByEmployee.get(emp.id) ?? []).filter((d) => d.calendarDate >= period.startDate && d.calendarDate <= period.endDate);
      for (const day of employeeDays) {
        const { dayType, payImpact } = this.classifyDay(day.status);
        await this.repos(manager).dayClassifications.save(
          this.repos(manager).dayClassifications.create({ payrollRunLineId: line.id, calendarDate: day.calendarDate, attendanceStatus: day.status, dayType, payImpact }),
        );
      }
    }

    await this.processEngine.transition(PAYROLL_RUN_PROCESS, RUN_ENTITY_TYPE, run.id, isNew ? 'calculate' : 'recalculate', actorUserId, manager);
    run.status = 'calculated';
    run.calculatedAt = now;
    await this.repos(manager).runs.save(run);

    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'payroll.run.calculated',
      resource: 'payroll_run',
      resourceId: run.id,
      result: 'success',
      correlationId: null,
      after: { payrollPeriodId, employeeCount: eligible.length },
    }, manager);
    return run;
  }

  async review(runId: string, actorUserId: string, manager?: EntityManager): Promise<PayrollRun> {
    const run = await this.repos(manager).runs.findOne({ where: { id: runId } });
    if (!run) throw new NotFoundException(`PayrollRun "${runId}" not found.`);
    await this.processEngine.transition(PAYROLL_RUN_PROCESS, RUN_ENTITY_TYPE, runId, 'review', actorUserId, manager);
    run.status = 'reviewed';
    run.reviewedByUserId = actorUserId;
    run.reviewedAt = new Date();
    const saved = await this.repos(manager).runs.save(run);
    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'payroll.run.reviewed',
      resource: 'payroll_run',
      resourceId: runId,
      result: 'success',
      correlationId: null,
    }, manager);
    return saved;
  }

  /** FA-01 submission — the one human control point (ADR-070 §5/§10). `approved -> posted` is automatic afterward, not a second submission. */
  async submitForApproval(runId: string, actorUserId: string, manager?: EntityManager): Promise<PayrollRun> {
    const run = await this.repos(manager).runs.findOne({ where: { id: runId } });
    if (!run) throw new NotFoundException(`PayrollRun "${runId}" not found.`);
    const state = await this.processEngine.getState(PAYROLL_RUN_PROCESS, RUN_ENTITY_TYPE, runId, manager);
    if (state !== 'reviewed') throw new ConflictException(`PayrollRun must be "reviewed" before FA-01 submission (current: "${state}").`);

    const lines = await this.repos(manager).runLines.find({ where: { payrollRunId: runId } });
    const totalNet = lines.reduce((sum, l) => sum + Number(l.netPay), 0);

    const approvalRequest = await this.approvals.submit({
      requestTypeCode: APPROVAL_TYPE,
      resourceType: RUN_ENTITY_TYPE,
      resourceId: runId,
      requestedAction: 'approve',
      payload: { payrollRunId: runId, employeeCount: lines.length, totalNet: totalNet.toFixed(2) },
      makerUserId: actorUserId,
    }, manager);
    run.approvalRequestId = approvalRequest.id;
    const saved = await this.repos(manager).runs.save(run);
    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'payroll.run.submitted',
      resource: 'payroll_run',
      resourceId: runId,
      result: 'success',
      correlationId: approvalRequest.id,
    }, manager);
    return saved;
  }

  /** Pure pass-through to the generic engine — same shape as every other FA-01 consumer's own `decide` (e.g. `AttendanceService.decide`). */
  async decide(requestId: string, approverUserId: string, decision: 'approved' | 'rejected', note?: string | null, manager?: EntityManager): Promise<unknown> {
    return this.approvals.decide(requestId, approverUserId, decision, note ?? null, manager);
  }

  async listRuns(manager?: EntityManager): Promise<PayrollRun[]> {
    return this.repos(manager).runs.find({ order: { createdAt: 'DESC' } });
  }

  async getRun(id: string, manager?: EntityManager): Promise<{ run: PayrollRun; lines: PayrollRunLine[] }> {
    const run = await this.repos(manager).runs.findOne({ where: { id } });
    if (!run) throw new NotFoundException(`PayrollRun "${id}" not found.`);
    const lines = await this.repos(manager).runLines.find({ where: { payrollRunId: id } });
    return { run, lines };
  }

  /**
   * The Frontend's own explicit three-state distinction requirement:
   * `PayrollRun.status`, `FinancialEvent.status`, and Treasury
   * disbursement are never the same state (`ADR-070 §6`). Returns `null`
   * when no `FinancialEvent` has landed yet (the run hasn't reached
   * `posted`, or the outbox hasn't dispatched it yet) — the UI must show
   * this as its own distinct "not yet posted" state, never blank/error.
   */
  async getFinancialEventStatus(runId: string, manager?: EntityManager): Promise<{ status: string; rejectionReason: string | null; journalEntryId: string | null } | null> {
    const [event]: Array<{ status: string; rejectionReason: string | null; journalEntryId: string | null }> = await this.em(manager).query(
      `SELECT status, "rejectionReason", "journalEntryId" FROM accounting_financial_events WHERE "sourceEntityType" = 'PayrollRun' AND "sourceEntityId"::text = $1`,
      [runId],
    );
    return event ?? null;
  }

  async listDayClassifications(payrollRunLineId: string, manager?: EntityManager): Promise<PayrollAttendanceDayClassification[]> {
    return this.repos(manager).dayClassifications.find({ where: { payrollRunLineId }, order: { calendarDate: 'ASC' } });
  }

  // ---------------------------------------------------------------------------
  // FA-01 subscriber — approved -> posted is automatic (ADR-070 §5's own
  // correction), never a second human action. Publishes the Financial
  // Event; does NOT wait for or assume GL posting succeeded (ADR-070 §6/§13).
  // ---------------------------------------------------------------------------

  private async onApprovalApproved(payload: Record<string, unknown>, manager?: EntityManager): Promise<void> {
    const requestTypeCode = String(payload.requestTypeCode ?? '');
    if (requestTypeCode !== APPROVAL_TYPE) return;
    const resourceId = String(payload.resourceId ?? '');
    const run = await this.repos(manager).runs.findOne({ where: { id: resourceId } });
    if (!run || run.status === 'posted') return; // not found, or already applied — benign no-op

    const lines = await this.repos(manager).runLines.find({ where: { payrollRunId: run.id } });
    const totalGross = lines.reduce((sum, l) => sum + Number(l.grossPay), 0);
    const totalNet = lines.reduce((sum, l) => sum + Number(l.netPay), 0);

    await this.em(manager).transaction(async (manager) => {
      await this.processEngine.transition(PAYROLL_RUN_PROCESS, RUN_ENTITY_TYPE, run.id, 'approve', SYSTEM_ACTOR_ID, manager);
      await this.processEngine.transition(PAYROLL_RUN_PROCESS, RUN_ENTITY_TYPE, run.id, 'post', SYSTEM_ACTOR_ID, manager);

      run.status = 'posted';
      run.approvedAt = new Date();
      run.postedAt = new Date();
      await manager.getRepository(PayrollRun).save(run);

      // ADR-070 §13 — this is the ONE Payroll transaction: process transitions + the outbox row,
      // then COMMIT. GL Journal Posting happens later, in a separate transaction, when
      // EventBusService.dispatchPending() invokes the registered Financial Event handler.
      // `sourceEntityType`/`sourceEntityId` are explicit (not left to FinancialEventService's own
      // `eventType.split('.')[1]` default, which would resolve to 'run', not 'PayrollRun') — this
      // is the exact pair ADR-070 §6's reconciliation invariant and listReconciliationGaps() key on.
      await this.events.publish(manager, 'payroll.run.posted', {
        sourceEntityType: RUN_ENTITY_TYPE,
        sourceEntityId: run.id,
        payrollRunId: run.id,
        payrollPeriodId: run.payrollPeriodId,
        totalGross: totalGross.toFixed(2),
        totalNet: totalNet.toFixed(2),
        employeeCount: lines.length,
      });
    });

    // This handler is itself invoked from inside ApprovalEngineService.decide's own
    // dispatchPending() pass (approval-engine.service.ts:307) — the outbox row just published
    // above did not exist when that pass started, so it will not be drained by it. Same explicit
    // "the publisher dispatches" convention every other service in this codebase follows
    // (WorkOrderService, TreasuryService, InvoicesService, ...).
    await this.events.dispatchAfterCommit(manager);

    await this.audit.record({
      actorUserId: SYSTEM_ACTOR_ID,
      organizationId: null,
      action: 'payroll.run.posted',
      resource: 'payroll_run',
      resourceId: run.id,
      result: 'success',
      correlationId: String(payload.approvalRequestId ?? ''),
      after: { totalGross: totalGross.toFixed(2), totalNet: totalNet.toFixed(2) },
    }, manager);
  }

  // ---------------------------------------------------------------------------
  // Reconciliation — ADR-070 §6/§15. The concrete, queryable detector for
  // "PayrollRun posted + GL not confirmed" — never assumed benign.
  // ---------------------------------------------------------------------------

  async listReconciliationGaps(manager?: EntityManager): Promise<Array<{ payrollRunId: string; code: string }>> {
    const rows: Array<{ id: string; code: string }> = await this.em(manager).query(`
      SELECT pr.id, pr.code FROM payroll_runs pr
      LEFT JOIN accounting_financial_events fe
        ON fe."sourceEntityType" = 'PayrollRun' AND fe."sourceEntityId"::text = pr.id::text
      WHERE pr.status = 'posted'
        AND (fe.id IS NULL OR fe.status NOT IN ('POSTED'))
    `);
    return rows.map((r) => ({ payrollRunId: r.id, code: r.code }));
  }

  // ---------------------------------------------------------------------------
  // Disbursement — ADR-070 §9/§13. A separate, explicitly human-invoked
  // action, never automatic — mirrors the existing, already-proven
  // `SupplierPaymentService.recordPayment` precedent exactly (its own
  // dedicated controller endpoint, never auto-cascaded from GL posting).
  // Gated on `FinancialEvent.status = 'POSTED'`, never on
  // `PayrollRun.postedAt` alone (ADR-070 §6's invariant is precisely why
  // this check is mandatory).
  // ---------------------------------------------------------------------------

  async disburse(runId: string, treasuryAccountId: string, actorUserId: string, manager?: EntityManager): Promise<PayrollRun> {
    const run = await this.repos(manager).runs.findOne({ where: { id: runId } });
    if (!run) throw new NotFoundException(`PayrollRun "${runId}" not found.`);
    if (run.status !== 'posted') throw new ConflictException(`PayrollRun "${runId}" must be "posted" before disbursement (current: "${run.status}").`);
    if (run.disbursedAt) throw new ConflictException(`PayrollRun "${runId}" has already been disbursed.`);

    const [event]: Array<{ status: string }> = await this.em(manager).query(
      `SELECT status FROM accounting_financial_events WHERE "sourceEntityType" = 'PayrollRun' AND "sourceEntityId"::text = $1`,
      [runId],
    );
    if (!event || event.status.toUpperCase() !== 'POSTED') {
      throw new ConflictException(
        `PayrollRun "${runId}" cannot be disbursed — its Financial Event has not resolved POSTED (current: "${event?.status ?? 'none — not yet dispatched'}"). ADR-070 §9: disbursement never proceeds on PayrollRun.posted alone.`,
      );
    }

    const lines = await this.repos(manager).runLines.find({ where: { payrollRunId: runId } });

    await this.em(manager).transaction(async (manager) => {
      // Advisory lock + a fresh re-check inside the transaction — the same idempotency/
      // duplicate-disbursement guard shape SupplierPaymentService.recordPayment already proves.
      await manager.query('SELECT pg_advisory_xact_lock(hashtext($1))', [`payroll:disburse:${runId}`]);
      const fresh = await manager.getRepository(PayrollRun).findOne({ where: { id: runId } });
      if (fresh?.disbursedAt) throw new ConflictException(`PayrollRun "${runId}" has already been disbursed.`);

      for (const line of lines) {
        await this.treasury.cashOutForEmployee(treasuryAccountId, line.netPay, line.employeeId, runId, `Payroll ${run.code}`, 'payroll_disbursement', actorUserId, manager);
      }

      run.disbursedAt = new Date();
      await manager.getRepository(PayrollRun).save(run);
    });

    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'payroll.run.disbursed',
      resource: 'payroll_run',
      resourceId: runId,
      result: 'success',
      correlationId: null,
      after: { treasuryAccountId, employeeCount: lines.length, totalNet: lines.reduce((s, l) => s + Number(l.netPay), 0).toFixed(2) },
    }, manager);
    return run;
  }

  // ---------------------------------------------------------------------------
  // Correction — ADR-070 §18. No PayrollRunLine/PayrollDeductionLine row is
  // ever updated after its run is posted; only a new PayrollAdjustment row
  // may reference it.
  // ---------------------------------------------------------------------------

  async createAdjustment(input: CreateAdjustmentInput, actorUserId: string, manager?: EntityManager): Promise<PayrollAdjustment> {
    const line = await this.repos(manager).runLines.findOne({ where: { id: input.originalPayrollRunLineId } });
    if (!line) throw new NotFoundException(`PayrollRunLine "${input.originalPayrollRunLineId}" not found.`);

    const saved = await this.repos(manager).adjustments.save(
      this.repos(manager).adjustments.create({
        originalPayrollRunLineId: input.originalPayrollRunLineId,
        kind: input.kind,
        reason: input.reason,
        amountDelta: input.amountDelta,
        createdByUserId: actorUserId,
      }),
    );
    await this.audit.record({
      actorUserId,
      organizationId: null,
      action: 'payroll.adjustment.created',
      resource: 'payroll_adjustment',
      resourceId: saved.id,
      result: 'success',
      correlationId: null,
      after: { originalPayrollRunLineId: input.originalPayrollRunLineId, kind: input.kind, amountDelta: input.amountDelta, reason: input.reason },
    }, manager);
    return saved;
  }

  async listAdjustments(originalPayrollRunLineId?: string, manager?: EntityManager): Promise<PayrollAdjustment[]> {
    return this.repos(manager).adjustments.find({ where: originalPayrollRunLineId ? { originalPayrollRunLineId } : {}, order: { createdAt: 'DESC' } });
  }
}

import { PlatformGuard, RequirePlatform } from '../platform/platform.guard';
import { Controller, Get, Param, Query, Req, UnauthorizedException, UseGuards } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { JwtAuthGuard, AuthenticatedRequest } from '../authentication/jwt-auth.guard';
import { RolesGuard } from '../authorization/roles.guard';
import { RequireRole } from '../authorization/require-role.decorator';
import { CompanyConnectionManagerService } from '../database-registry/company-connection-manager.service';
import { AuditService } from './audit.service';
import { AuditRecord } from './audit-record.entity';
import { runOperationalAdmitted } from '../company/company-lifecycle-admission';
import { CompanyNotReadyException } from '../company/company-operational-status';

/**
 * Area 14 (2026-09-25, CTO Implementation Gate). The SEPARATE
 * Installation-level administrative audit path — gated by the PLATFORM
 * `admin` role via `RolesGuard`, never `CompanyContextGuard`. Same
 * precedent as `InstallationMembershipController`: a platform admin is
 * trusted to name any Company explicitly (`:companyId` as a real route
 * param), for control-plane administrative purposes — the Company
 * self-service boundary (`CompanyAuditController`) is entirely untouched
 * by this controller's existence.
 */
@Controller('installation/companies/:companyId/audit')
@UseGuards(JwtAuthGuard, PlatformGuard)
export class InstallationAuditController {
  constructor(
    private readonly connections: CompanyConnectionManagerService,
    private readonly audit: AuditService,
    private readonly platform: DataSource,
  ) {}

  @RequirePlatform('platform.audit.view')
  @Get()
  async list(@Req() req: AuthenticatedRequest, @Param('companyId') companyId: string, @Query('action') action?: string, @Query('take') take?: string) {
    if (!req.user) throw new UnauthorizedException();
    const userId = req.user.id;

    // LA-1 Layer 2 (DP-9 O-3): reading a Company's database is Company operational access — a platform
    // admin gets NO implicit override. Admission joins the READY check with the DataSource use; a
    // non-READY Company yields the same 409 COMPANY_NOT_READY as Layer 1 and nothing is opened.
    const admission = await runOperationalAdmitted(this.platform, this.connections, companyId, async (dataSource) => {
      const where = action ? { action } : {};
      const records = await dataSource.getRepository(AuditRecord).find({ where, order: { seq: 'DESC' }, take: take ? Number(take) : 100 });

      await this.audit.record(
        {
          actorUserId: userId,
          organizationId: null,
          action: 'company.audit.accessed',
          resource: 'audit_record',
          resourceId: null,
          result: 'success',
          correlationId: null,
          after: { filter: { action: action ?? null }, count: records.length, accessedByInstallationAdmin: true },
        },
        dataSource.manager,
      );
      return records;
    });
    if (!admission.admitted) throw new CompanyNotReadyException();

    return { success: true, data: admission.value };
  }
}

import { Injectable } from '@nestjs/common';
import { DataSource, EntityManager } from 'typeorm';
import { PermissionAccess } from '../permission/role-permission.entity';
import { AuthorizationContext } from './authorization-context';
import { loadAuthorizationContext } from './authorization-context.loader';

/** What a request needs to carry for the context to be derived from it. Matches `CompanyScopedRequest` (the Company context is set by `CompanyContextGuard`). */
export interface ContextRequest {
  user?: { id: string; companyId?: string };
  companyContext?: { companyId: string; dataSource: { manager: EntityManager } };
}

const REQUEST_CACHE = Symbol('daii.authorizationContext');
interface CachedEntry {
  managerKey: object | null;
  promise: Promise<AuthorizationContext>;
}

/**
 * Authorization Program F1.1 — resolves the `AuthorizationContext` ONCE per request and memoizes it on the request object, so `RolesGuard`,
 * `PermissionGuard`, navigation and `/auth/me` share one load (ONE statement: the user's roles joined to their `role_permissions`).
 *
 * Fail-closed by construction: the load either yields the real roles/grants or throws; a thrown/rejected load is never cached as an empty
 * context and the guards let the error deny the request (they never fall back to "allow"). The cache lives ONLY on the request object — nothing
 * is shared across requests, so a role change takes effect on the very next request (no stale-allow window).
 *
 * Authorization domain: when a Company manager is supplied (validated `CompanyContextGuard` / `CompanyViewContextService`) the roles and grants
 * are read from THAT Company's own database; with no manager they come from the ambient (platform) tables — identical to the pre-F1 behaviour
 * of `RolesGuard` / `PermissionService`.
 */
@Injectable()
export class AuthorizationContextService {
  constructor(private readonly dataSource: DataSource) {}

  /** The memoized context for the request's authenticated user. `manager` overrides the one on `req.companyContext` (used by routes that validate the Company themselves, e.g. `/me/navigation`). */
  forRequest(req: ContextRequest, manager?: EntityManager): Promise<AuthorizationContext> {
    if (!req.user) return Promise.reject(new Error('AuthorizationContext requires an authenticated request.'));
    const m = manager ?? req.companyContext?.dataSource.manager;
    const bag = req as unknown as Record<symbol, CachedEntry | undefined>;
    const hit = bag[REQUEST_CACHE];
    if (hit && hit.managerKey === (m ?? null)) return hit.promise;
    const companyId = m ? (req.companyContext?.companyId ?? req.user.companyId ?? null) : null;
    const promise = this.load(req.user.id, companyId, m);
    // never cache a failure: a transient error must not become a sticky (or empty) context
    promise.catch(() => {
      if (bag[REQUEST_CACHE]?.promise === promise) bag[REQUEST_CACHE] = undefined;
    });
    bag[REQUEST_CACHE] = { managerKey: m ?? null, promise };
    return promise;
  }

  /**
   * B2 (2026-10-08) — the FIRST load of the request's context, performed by `combined` together with other rows the caller needs (one statement, one round
   * trip, e.g. the access scope). The context is memoized exactly like `forRequest` (same cache entry, same never-cache-a-failure rule), so every later guard /
   * handler reuses it. Returns `null` when the request already holds a context for this manager — the caller then loads its own rows separately.
   * `combined` must build the context with `buildAuthorizationContext` from `AUTHORIZATION_CONTEXT_FROM` rows (the one definition of "what a user holds").
   */
  forRequestWith<T>(
    req: ContextRequest,
    manager: EntityManager,
    combined: (userId: string, companyId: string | null) => Promise<{ ctx: AuthorizationContext; extra: T }>,
  ): { ctx: Promise<AuthorizationContext>; extra: Promise<T> } | null {
    if (!req.user) return null;
    const bag = req as unknown as Record<symbol, CachedEntry | undefined>;
    const hit = bag[REQUEST_CACHE];
    if (hit && hit.managerKey === manager) return null;
    const companyId = req.companyContext?.companyId ?? req.user.companyId ?? null;
    const both = combined(req.user.id, companyId);
    const promise = both.then((r) => r.ctx);
    promise.catch(() => {
      if (bag[REQUEST_CACHE]?.promise === promise) bag[REQUEST_CACHE] = undefined;
    });
    bag[REQUEST_CACHE] = { managerKey: manager, promise };
    const extra = both.then((r) => r.extra);
    extra.catch(() => undefined); // observed: a caller that stops at the context's failure must not leave an unhandled rejection (awaiting callers still receive it)
    return { ctx: promise, extra };
  }

  /**
   * Uncached load for callers with no request object (batch jobs, tests).
   *
   * ONE statement: the user's roles joined to every `role_permissions` row of those roles (LEFT JOIN, so a role with no grants still appears as a
   * role). Pre-F1 each permission check cost 4 statements (user_roles, roles, role ids, grants).
   */
  async load(userId: string, companyId: string | null, manager?: EntityManager): Promise<AuthorizationContext> {
    return loadAuthorizationContext(manager ?? this.dataSource, userId, companyId);
  }
}

import { randomUUID } from 'crypto';
import { spawn } from 'child_process';
import { join } from 'path';
import { DataSource } from 'typeorm';
import { Company } from './company.entity';
import { User } from '../identity/user.entity';
import { UsersService } from '../identity/users.service';
import { DatabaseRegistryUniqueDatabaseName1790011000000 } from '../../database/migrations/core/1790011000000-DatabaseRegistryUniqueDatabaseName';

/**
 * Passenger may run several Node workers. N SEPARATE OS processes (not N async calls in one process) create Companies at the same instant over one control-plane
 * database and a pool smaller than N: the database alone must keep every pooled database single-owner, and no Company row may be left behind by the losers.
 */
const HOST = process.env.DB_HOST ?? '127.0.0.1';
const PORT = process.env.DB_PORT ? Number(process.env.DB_PORT) : 0;
const ADMIN = process.env.DB_USER ?? '';
const ADMIN_PW = process.env.DB_PASSWORD ?? '';
const describeIsolated = PORT && PORT !== 5433 && ADMIN ? describe : describe.skip;
const tag = randomUUID().slice(0, 6);
const CP = `daii_test_mp_cp_${tag}`;

describeIsolated('Company database pool — several OS processes at once (real Postgres, isolated instance only)', () => {
  jest.setTimeout(900_000);
  const toDrop: string[] = [CP];
  let cp: DataSource;
  let adminUserId: string;
  const adminCfg = { type: 'postgres' as const, host: HOST, port: PORT, username: ADMIN, password: ADMIN_PW, database: 'postgres' };
  const withAdmin = async <T>(fn: (ds: DataSource) => Promise<T>): Promise<T> => {
    const ds = new DataSource(adminCfg);
    await ds.initialize();
    try { return await fn(ds); } finally { await ds.destroy(); }
  };

  const runWorker = (pool: string[], name: string) =>
    new Promise<{ ok: boolean; companyId?: string; code?: string | null; message?: string }>((resolve, reject) => {
      const child = spawn(process.execPath, ['-r', 'ts-node/register/transpile-only', join(process.cwd(), 'src/foundation/testing/company-pool-worker.ts')], {
        env: { ...process.env, TS_NODE_PROJECT: join(process.cwd(), 'tsconfig.json'), WORKER_CP_DB: CP, WORKER_POOL: JSON.stringify(pool), WORKER_NAME: name, WORKER_ADMIN: adminUserId },
        cwd: process.cwd(),
      });
      let out = '', err = '';
      child.stdout.on('data', (d) => (out += d));
      child.stderr.on('data', (d) => (err += d));
      child.on('close', () => {
        const line = out.split('\n').find((l) => l.startsWith('RESULT '));
        line ? resolve(JSON.parse(line.slice(7))) : reject(new Error(`worker produced no result: ${err.slice(-800)}`));
      });
    });

  beforeAll(async () => {
    await withAdmin((ds) => ds.query(`CREATE DATABASE "${CP}"`));
    const { runMigrationsForDatabase } = await import('../release-orchestration/company-migration-runner');
    const migrated = await runMigrationsForDatabase(process.cwd(), { host: HOST, port: PORT, username: ADMIN, password: ADMIN_PW, database: CP }, ['core']);
    if (!migrated.success) throw new Error(`control-plane migration failed: ${migrated.error}`);
    cp = new DataSource({ type: 'postgres', host: HOST, port: PORT, username: ADMIN, password: ADMIN_PW, database: CP, entities: [Company, User], synchronize: false });
    await cp.initialize();
    await cp.query(`INSERT INTO "installation" ("id","installationId","customerName","editionCode","editionVersion","entitlementManifest") VALUES ('installation','test-installation','Test','DAII_STANDARD','1.0.0','{}')`);
    adminUserId = (await new UsersService(cp.getRepository(User)).create({ fullName: 'MP Admin', email: `mp-admin-${tag}@test.local` })).id;
  });
  afterAll(async () => {
    await cp?.destroy();
    await withAdmin(async (ds) => { for (const d of toDrop) await ds.query(`DROP DATABASE IF EXISTS "${d}" WITH (FORCE)`); });
  });

  it('the migration created the unique index, and the database itself refuses a second registration of a database name', async () => {
    expect((await cp.query(`SELECT 1 FROM pg_indexes WHERE indexname='UQ_database_registries_databaseName'`)).length).toBe(1);
    const c1 = (await cp.query(`INSERT INTO companies ("installationId", name, status) VALUES ('installation','u1','PROVISIONING') RETURNING id`))[0].id;
    const c2 = (await cp.query(`INSERT INTO companies ("installationId", name, status) VALUES ('installation','u2','PROVISIONING') RETURNING id`))[0].id;
    await cp.query(`INSERT INTO database_registries ("companyId", host, port, "databaseName", status) VALUES ($1,'h',1,'dup_db','PROVISIONING')`, [c1]);
    await expect(cp.query(`INSERT INTO database_registries ("companyId", host, port, "databaseName", status) VALUES ($1,'h',1,'dup_db','PROVISIONING')`, [c2])).rejects.toThrow(/UQ_database_registries_databaseName/);
    await cp.query(`DELETE FROM database_registries WHERE "databaseName"='dup_db'`);
    await cp.query(`DELETE FROM companies WHERE id IN ($1,$2)`, [c1, c2]);
  });

  it('the migration refuses (and changes nothing) when duplicates already exist, naming them', async () => {
    const c1 = (await cp.query(`INSERT INTO companies ("installationId", name, status) VALUES ('installation','d1','PROVISIONING') RETURNING id`))[0].id;
    const c2 = (await cp.query(`INSERT INTO companies ("installationId", name, status) VALUES ('installation','d2','PROVISIONING') RETURNING id`))[0].id;
    await cp.query(`DROP INDEX "UQ_database_registries_databaseName"`);
    await cp.query(`INSERT INTO database_registries ("companyId", host, port, "databaseName", status) VALUES ($1,'h',1,'same_db','FAILED'), ($2,'h',1,'same_db','FAILED')`, [c1, c2]);
    const qr = cp.createQueryRunner();
    await expect(new DatabaseRegistryUniqueDatabaseName1790011000000().up(qr)).rejects.toThrow(/same_db x2/);
    expect((await cp.query(`SELECT count(*)::int n FROM database_registries WHERE "databaseName"='same_db'`))[0].n).toBe(2); // untouched
    await qr.release();
    await cp.query(`DELETE FROM database_registries WHERE "databaseName"='same_db'`);
    await cp.query(`DELETE FROM companies WHERE id IN ($1,$2)`, [c1, c2]);
    await new DatabaseRegistryUniqueDatabaseName1790011000000().up(cp.createQueryRunner());
    expect((await cp.query(`SELECT 1 FROM pg_indexes WHERE indexname='UQ_database_registries_databaseName'`)).length).toBe(1);
  });

  it('6 separate processes, 3 pooled databases: exactly 3 Companies are created, every database has ONE owner, and the losers leave no Company behind', async () => {
    const pool = ['mp_a', 'mp_b', 'mp_c'].map((n) => `${n}_${tag}`);
    for (const d of pool) { toDrop.push(d); await withAdmin((ds) => ds.query(`CREATE DATABASE "${d}"`)); }
    const before = (await cp.query(`SELECT count(*)::int n FROM companies`))[0].n;

    const results = await Promise.all(Array.from({ length: 6 }, (_, i) => runWorker(pool, `W${i}`)));

    const ok = results.filter((r) => r.ok);
    const refused = results.filter((r) => !r.ok);
    expect(refused.map((r) => r.code)).toEqual(Array(3).fill('COMPANY_DATABASE_POOL_EXHAUSTED'));
    expect(ok).toHaveLength(3);
    const regs: Array<{ databaseName: string; status: string; companyId: string }> = await cp.query(`SELECT "databaseName", status, "companyId" FROM database_registries WHERE "databaseName" = ANY($1)`, [pool]);
    expect(regs.map((r) => r.databaseName).sort()).toEqual([...pool].sort()); // each pooled database registered exactly once
    expect(regs.every((r) => r.status === 'ACTIVE')).toBe(true);
    expect((await cp.query(`SELECT count(*)::int n FROM companies`))[0].n).toBe(before + 3); // no orphan Company from the losers
    expect((await cp.query(`SELECT count(*)::int n FROM companies WHERE status='PROVISIONING'`))[0].n).toBe(0);
  });
});

import { DataSource } from 'typeorm';
import { CompanyActivationService } from './company-activation.service';
import { CompanyRegistryService } from './company-registry.service';
import { runOperationalAdmitted } from './company-lifecycle-admission';
import { PreliminaryHoldExpiryScheduler } from '../../domains/sales-orders/application/preliminary-hold-expiry.scheduler';
import { ApprovalExpiryScheduler } from '../approval-engine/approval-expiry.scheduler';
import { setUpTwoCompanyHarness, TwoCompanyHarness } from '../testing/two-company-real-pg-harness';

/**
 * LA-1 — Lifecycle Admission Boundary, Layer 2: REAL-POSTGRES + two-Company ISOLATION proof
 * (CTO Executive Order 2026-10-06). Real: Platform DB `companies` row locks, CompanyActivationService
 * (the real `suspend`/`decommission` UPDATE), CompanyConnectionManagerService, two real Company
 * databases, the real PreliminaryHoldExpiryScheduler and ApprovalExpiryScheduler classes. Doubles:
 * only the business collaborators those schedulers call (inventory / sales-orders / approval engine).
 */
describe('LA-1 — Layer 2 lifecycle admission (non-HTTP operational paths), real-Postgres + A/B isolation', () => {
  jest.setTimeout(300_000);
  let h: TwoCompanyHarness;
  let activation: CompanyActivationService;
  let getDataSourceSpy: jest.SpyInstance;

  const platform = () => h.controlPlane as DataSource;
  const dbOf = async (ds: DataSource) => (await ds.query(`SELECT current_database() AS db`))[0].db as string;
  const setStatus = (id: string, status: string) => h.controlPlane.query(`UPDATE "companies" SET "status" = $1 WHERE "id" = $2`, [status, id]);
  const statusOf = async (id: string) => (await h.controlPlane.query(`SELECT "status" FROM "companies" WHERE "id" = $1`, [id]))[0].status as string;
  const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

  beforeAll(async () => {
    h = await setUpTwoCompanyHarness({ namePrefix: 'la1_layer2', roleModuleCodes: ['sales'] });
    activation = new CompanyActivationService(new CompanyRegistryService(h.companies));
    getDataSourceSpy = jest.spyOn(h.connections, 'getDataSource');
  });

  afterAll(async () => {
    await h.teardown();
  });

  beforeEach(async () => {
    await setStatus(h.companyAId, 'READY');
    await setStatus(h.companyBId, 'READY');
    getDataSourceSpy.mockClear();
  });

  it('READY → admitted: the work runs against that Company\'s own database only', async () => {
    const result = await runOperationalAdmitted(platform(), h.connections, h.companyAId, (ds) => dbOf(ds));
    expect(result).toEqual({ admitted: true, value: h.companyADbName });
    expect(getDataSourceSpy).toHaveBeenCalledTimes(1);
    expect(getDataSourceSpy).toHaveBeenCalledWith(h.companyAId);
  });

  it.each(['SUSPENDED', 'DECOMMISSIONED', 'PROVISIONING', 'DEGRADED', 'MIGRATING', 'FAILED'])('%s → refused: the work does not run and the Company DataSource is NEVER requested', async (status) => {
    await setStatus(h.companyAId, status);
    const work = jest.fn(async () => 'ran');
    const result = await runOperationalAdmitted(platform(), h.connections, h.companyAId, work);
    expect(result).toMatchObject({ admitted: false, reason: 'COMPANY_NOT_READY', status });
    expect(work).not.toHaveBeenCalled();
    expect(getDataSourceSpy).not.toHaveBeenCalled();
  });

  it('an unknown Company id is refused (MISSING) and opens nothing', async () => {
    const work = jest.fn(async () => 'ran');
    const result = await runOperationalAdmitted(platform(), h.connections, '00000000-0000-4000-8000-000000000000', work);
    expect(result).toMatchObject({ admitted: false, status: 'MISSING' });
    expect(work).not.toHaveBeenCalled();
    expect(getDataSourceSpy).not.toHaveBeenCalled();
  });

  it('ISOLATION — while A is SUSPENDED, B is admitted and reaches only B\'s database; A is never opened', async () => {
    await activation.suspend(h.companyAId);
    const a = await runOperationalAdmitted(platform(), h.connections, h.companyAId, (ds) => dbOf(ds));
    const b = await runOperationalAdmitted(platform(), h.connections, h.companyBId, (ds) => dbOf(ds));
    expect(a.admitted).toBe(false);
    expect(b).toEqual({ admitted: true, value: h.companyBDbName });
    expect(getDataSourceSpy).toHaveBeenCalledTimes(1);
    expect(getDataSourceSpy).toHaveBeenCalledWith(h.companyBId);
    expect(getDataSourceSpy).not.toHaveBeenCalledWith(h.companyAId);
  });

  it('RACE (V-08) — a suspend() issued while admitted work is in flight WAITS for it; the change only commits after the work ends; any admission after it is refused', async () => {
    const timeline: string[] = [];
    let release!: () => void;
    const latch = new Promise<void>((r) => (release = r));
    let started!: () => void;
    const workStarted = new Promise<void>((r) => (started = r));

    const inFlight = runOperationalAdmitted(platform(), h.connections, h.companyAId, async () => {
      timeline.push('work-start');
      started();
      await latch;
      timeline.push('work-end');
    });
    await workStarted;

    const suspending = activation.suspend(h.companyAId).then(() => timeline.push('suspend-committed'));
    await sleep(750);
    expect(timeline).toEqual(['work-start']); // suspend is blocked behind the in-flight admitted work
    expect(await statusOf(h.companyAId)).toBe('READY'); // the flip is not visible yet

    // An admission that arrives while the suspend is still pending may legitimately start (the flip has not
    // committed) — but then the suspend waits for it too. What must never happen is work AFTER the flip.
    const lateStart = runOperationalAdmitted(platform(), h.connections, h.companyAId, async () => {
      timeline.push('late-work');
    });

    release();
    await inFlight;
    await suspending;
    await lateStart;

    expect(timeline[timeline.length - 1]).toBe('suspend-committed'); // every admitted piece of work finished BEFORE the flip became visible
    expect(timeline.indexOf('work-end')).toBeLessThan(timeline.indexOf('suspend-committed'));
    expect(await statusOf(h.companyAId)).toBe('SUSPENDED');
    const after = await runOperationalAdmitted(platform(), h.connections, h.companyAId, async () => 'x');
    expect(after.admitted).toBe(false);
  });

  it('work that throws releases the lock: the error propagates, a following suspend() is not blocked, and nothing else is affected', async () => {
    await expect(
      runOperationalAdmitted(platform(), h.connections, h.companyAId, async () => {
        throw new Error('job exploded');
      }),
    ).rejects.toThrow('job exploded');
    const t0 = Date.now();
    await activation.suspend(h.companyAId);
    expect(Date.now() - t0).toBeLessThan(5000);
    expect(await statusOf(h.companyAId)).toBe('SUSPENDED');
  });

  it('SCHEDULED WORK (V-05) — PreliminaryHoldExpiryScheduler: A was READY when the sweep list was built but is SUSPENDED when its turn comes → A is skipped, B still runs against B only', async () => {
    const touched: string[] = [];
    const inventory = {
      findExpiredPreliminaryHoldOrderIds: async (_cutoff: Date, manager: { query: (q: string) => Promise<Array<{ db: string }>> }) => {
        touched.push((await manager.query(`SELECT current_database() AS db`))[0].db);
        return [];
      },
    };
    const scheduler = new PreliminaryHoldExpiryScheduler(inventory as never, { expireHoldForOrder: jest.fn() } as never, h.connections, platform());
    const listSpy = jest.spyOn(h.connections, 'listActiveCompanyIds').mockImplementation(async () => {
      const ids = [h.companyAId, h.companyBId];
      await activation.suspend(h.companyAId); // suspended AFTER the list was built, BEFORE A's turn
      return ids;
    });
    try {
      await scheduler.runOnce();
    } finally {
      listSpy.mockRestore();
    }
    expect(touched).toEqual([h.companyBDbName]);
    expect(getDataSourceSpy).not.toHaveBeenCalledWith(h.companyAId);
  });

  it('SCHEDULED WORK (V-05) — ApprovalExpiryScheduler: a DECOMMISSIONED Company is skipped, the other Company\'s sweep still runs', async () => {
    await activation.suspend(h.companyAId);
    await activation.decommission(h.companyAId);
    const seen: string[] = [];
    const engine = { expire: async (ds: DataSource) => (seen.push(await dbOf(ds)), { expired: 0 }) };
    const scheduler = new ApprovalExpiryScheduler(engine as never, { get: () => true } as never, h.connections, platform());
    await scheduler.runOnce();
    expect(seen).toEqual([h.companyBDbName]);
    expect(getDataSourceSpy).not.toHaveBeenCalledWith(h.companyAId);
  });

  it('BACKUP SEPARATION (V-06 / N-08) — Layer-2 admission does not touch Backup/DR\'s own sweep set: a SUSPENDED Company stays in the registry-based list Backup uses (no implicit bypass, no flag, no change)', async () => {
    await activation.suspend(h.companyAId);
    const backupSweepSet = await h.connections.listActiveCompanyIds();
    expect(backupSweepSet).toContain(h.companyAId);
    expect(backupSweepSet).toContain(h.companyBId);
    expect(await statusOf(h.companyAId)).toBe('SUSPENDED');
  });
});

import { PlatformGuard, RequirePlatform } from '../platform/platform.guard';
import { BadRequestException, Body, Controller, Get, HttpStatus, NotFoundException, Param, Post, UnprocessableEntityException, UseGuards } from '@nestjs/common';
import { DaiiException } from '../error-contract/daii-exception';
import { EntitlementService } from '../entitlement/entitlement.service';
import { Logger } from '@nestjs/common';
import { allocateCompanyDatabase, CompanyDatabaseAllocationError, CompanyDatabaseConfig, CompanyDatabaseConfigError, ConnectionTarget, serializeAllocation } from './company-database-allocator';
import { ArrayNotEmpty, IsArray, IsOptional, IsString, IsUUID, MinLength } from 'class-validator';
import { JwtAuthGuard } from '../authentication/jwt-auth.guard';
import { RolesGuard } from '../authorization/roles.guard';
