class CreateCompanyDto {
  @IsString()
  @MinLength(1)
  name!: string;

  /** D1 (Area 20): must reference an EXISTING User — this endpoint never creates one. */
  @IsUUID()
  initialAdminUserId!: string;

  /**
   * Migration tags to run in the new Company's own database. Omitted =
   * `runMigrationsForDatabase`'s own existing default (auto-discover every
   * tag under `src/database/migrations/`) — not a new default invented
   * here, the pre-existing behavior when `tags` is left `undefined`.
   */
  @IsOptional()
  @IsArray()
  @ArrayNotEmpty()
  @IsString({ each: true })
  tags?: string[];

  /**
   * Module role-template catalogs to seed (Area 6). Omitted =
   * `DatabaseProvisioningService`'s own existing default (`[]` — "does not
   * guess an entitlement it has no way to know yet", per that service's
   * own doc comment). Not overridden with a different default here.
   */
  @IsOptional()
  @IsArray()
  @ArrayNotEmpty()
  @IsString({ each: true })
  roleModuleCodes?: string[];
}

/** PostgreSQL unique violation (23505) on `database_registries.databaseName`. */
function isDatabaseNameTaken(err: unknown): boolean {
  const e = err as { code?: string; driverError?: { code?: string; constraint?: string }; constraint?: string };
  const code = e?.driverError?.code ?? e?.code;
  const constraint = e?.driverError?.constraint ?? e?.constraint ?? '';
  return code === '23505' && /databaseName/i.test(constraint);
}

interface CompanyView {
  id: string;
  name: string;
  status: Company['status'];
  createdAt: Date;
  /** Null until a `DatabaseRegistry` row exists for this Company (i.e. before `DatabaseProvisioningService.provision()` has run at all). */
  databaseStatus: string | null;
}

/**
 * Multi-Company Control Plane — P0 (2026-09-27, CTO-authorized: "P0
 * Multi-Company Control-Plane HTTP Surface"). Exposes the EXISTING,
 * already-built, already-real-PG-verified `CompanyRegistryService` /
 * `CompanyActivationService` / `DatabaseProvisioningService` (Multi-Company
 * Phase 3 V7, Areas 2/4/19/20) through a real HTTP surface — this file adds
 * no new business logic, no new state machine, no new provisioning steps.
 *
 * Authorization: the SAME Installation-Administrator boundary this
 * codebase already established for exactly this kind of control-plane
 * operation — `installation-membership.controller.ts`'s own precedent
 * (`JwtAuthGuard` + `RolesGuard` + `@RequireRole('admin')`, never
 * `CompanyContextGuard` — a platform admin is trusted to name any Company
 * explicitly, for control-plane purposes, exactly as that controller's own
 * doc comment states). Not a new authorization axis.
 *
 * Installation Bootstrap (P0.1): resolved, not built here. The singleton
 * `Installation` row (`INSTALLATION_SINGLETON_ID`) this Company's
 * `installationId` FK requires is already created by the EXISTING
 * `POST /admin/entitlement/apply` (`EntitlementController`/
 * `EntitlementService.applyManifest`) — "the endpoint P6's deploy step
 * calls to apply a freshly-issued signed manifest." That IS the approved
 * bootstrap mechanism; this controller does not create an Installation row
 * itself, silently or otherwise — `POST /installation/companies` will
 * correctly fail with a clear error if no Installation row exists yet
 * (the real DB-level FK, not a guessed error path).
 */
@Controller('installation/companies')
@UseGuards(JwtAuthGuard, PlatformGuard)
export class CompanyRegistryController {
  private readonly logger = new Logger(CompanyRegistryController.name);

  constructor(
    private readonly companyRegistry: CompanyRegistryService,
    private readonly companyActivation: CompanyActivationService,
    private readonly databaseRegistry: DatabaseRegistryService,
    private readonly databaseProvisioning: DatabaseProvisioningService,
    private readonly config: AppConfigService,
    private readonly entitlement: EntitlementService,
  ) {}

  @RequirePlatform('platform.company.view')
  @Get()
  async list() {
    const companies = await this.companyRegistry.listVisible(INSTALLATION_SINGLETON_ID);
    const views = await Promise.all(companies.map((c) => this.toView(c)));
    return { success: true, data: views };
  }

  @RequirePlatform('platform.company.view')
  @Get(':id')
  async get(@Param('id') id: string) {
    const company = await this.companyRegistry.findById(id);
    if (!company) throw new NotFoundException(`Company not found: ${id}`);
    return { success: true, data: await this.toView(company) };
  }

  /**
   * Synchronous — see `docs/decisions/P0-MULTI-COMPANY-CONTROL-PLANE-API.md`
   * for why. Runs `CompanyRegistryService.provision()` (create, status
   * `PROVISIONING`) then immediately `DatabaseProvisioningService.provision()`
   * (the existing, unmodified, already-verified pipeline) in the same
   * request. On any provisioning-stage failure, the Company row itself is
   * NOT transitioned to a failure status by the existing service (a
   * pre-existing asymmetry — see the same doc) — its `DatabaseRegistry`
   * row IS marked `FAILED`, and `databaseStatus` in the response reflects
   * that even though `status` still reads `PROVISIONING`. Not corrected
   * here — that would be changing existing, already-verified service
   * behavior, out of this endpoint's scope.
   */
  @RequirePlatform('platform.company.create', 'editable')
  @Post()
  async create(@Body() dto: CreateCompanyDto) {
    // A Company's `installationId` is a foreign key to the platform installation row. Refuse BEFORE anything is created, with the real reason — the raw foreign-key
    // violation used to reach the operator as "An unexpected error occurred" (post-incident review of release 1.1.4).
    if (!(await this.entitlement.isInstallationInitialized())) {
      throw new DaiiException(
        'INSTALLATION_NOT_INITIALIZED',
        'The platform installation is not initialised, so a Company cannot be created yet. With ENTITLEMENT_MODE=unlicensed-full it is initialised automatically when the application starts; with ENTITLEMENT_MODE=enforced a signed entitlement manifest must be applied first (POST /api/admin/entitlement/apply).',
        HttpStatus.CONFLICT,
      );
    }
    // Create the PHYSICAL database FIRST. `companies.status` has no edge out of PROVISIONING except READY, so a Company row inserted before a failure here could never
    // be marked failed and would stay behind as an orphan PROVISIONING record. If the database user cannot reach the maintenance database or lacks CREATEDB (typical of a
    // shared PostgreSQL host), nothing has been created yet and the operator gets the real reason instead of "An unexpected error occurred".
    // The initial administrator must exist BEFORE anything is allocated or created: failing here later would leave a PROVISIONING Company and a consumed database.
    await this.assertInitialAdmin(dto.initialAdminUserId);
    let cfg: CompanyDatabaseConfig;
    try {
      cfg = this.config.companyDatabase;
    } catch (err) {
      // a mis-set COMPANY_DB_* variable is an operator-fixable configuration problem: say which one, before anything is allocated or created
      if (err instanceof CompanyDatabaseConfigError) {
        this.logger.error(`Company creation refused: ${err.message}`);
        throw new UnprocessableEntityException({ message: err.message, code: err.code, stage: 'configuration' });
      }
      throw err;
    }
    const app = { host: this.config.database.host, port: this.config.database.port, username: this.config.database.username, password: this.config.database.password };
    // Serialised so two concurrent creations cannot claim the same pooled database. The Company row follows the allocation, in the same critical section.
    return serializeAllocation(async () => {
      let allocated = await this.allocate(cfg, app);
      const company = await this.companyRegistry.provision(INSTALLATION_SINGLETON_ID, dto.name);
      // The in-process lock above does not cover other Node workers. The unique index on `database_registries.databaseName` is the real guard: if another worker registered the
      // database we just picked first, take the next one for the SAME Company; when the pool has nothing left, the still-bare Company row is discarded (never one that owns a registry row).
      for (let attempt = 0; ; attempt++) {
        try {
          return await this.createCompanyOn(dto, allocated.databaseName, company);
        } catch (err) {
          if (cfg.mode !== 'pool' || !isDatabaseNameTaken(err) || attempt >= 10) throw err;
          this.logger.warn(`Pooled database "${allocated.databaseName}" was taken by a concurrent request; claiming the next one.`);
          try {
            allocated = await this.allocate(cfg, app);
          } catch (exhausted) {
            await this.companyRegistry.discardUnprovisioned(company.id);
            throw exhausted;
          }
        }
      }
    });
  }

  private async allocate(cfg: CompanyDatabaseConfig, app: ConnectionTarget): Promise<{ databaseName: string; origin: 'created' | 'pooled' }> {
    try {
      return await allocateCompanyDatabase(cfg, app, () => this.databaseRegistry.usedDatabaseNames());
    } catch (err) {
      if (err instanceof CompanyDatabaseAllocationError) {
        this.logger.error(`Company database allocation failed (${err.code}): ${err.detail}`);
        throw new UnprocessableEntityException({ message: err.message, code: err.code, stage: cfg.mode === 'pool' ? 'claim-database' : 'create-database', detail: err.detail });
      }
      throw err;
    }
  }

  /**
   * Resume provisioning of a Company whose earlier attempt failed AFTER its database was allocated (migration / role-seeding fault). It reuses the SAME database and the
   * SAME Company row — no new allocation, no duplicate Company — through the provisioning service's existing retry/resume path.
   */
  @RequirePlatform('platform.company.create', 'editable')
  @Post(':id/retry-provisioning')
  async retryProvisioning(@Param('id') id: string, @Body() dto: CreateCompanyDto) {
    const company = await this.companyRegistry.findById(id);
    if (!company) throw new NotFoundException(`Company not found: ${id}`);
    if (company.status !== 'PROVISIONING') {
      throw new UnprocessableEntityException({ message: `Company is ${company.status}, only a PROVISIONING Company can be retried.`, code: 'COMPANY_NOT_RETRYABLE' });
    }
    const registry = await this.databaseRegistry.findByCompanyId(id);
    if (!registry) {
      throw new UnprocessableEntityException({ message: 'No database was ever allocated to this Company, so there is nothing to resume. Create the Company again.', code: 'COMPANY_NOT_RETRYABLE' });
    }
    await this.assertInitialAdmin(dto.initialAdminUserId);
    return this.createCompanyOn(dto, registry.databaseName, company);
  }

  private async assertInitialAdmin(userId: string): Promise<void> {
    try {
      await this.databaseProvisioning.assertInitialAdminExists(userId);
    } catch (err) {
      if (err instanceof NotFoundException) throw new BadRequestException(`initialAdminUserId does not reference an existing User: ${userId}`);
      throw err;
    }
  }

  private async createCompanyOn(dto: CreateCompanyDto, databaseName: string, existing?: Company) {
    const company = existing ?? (await this.companyRegistry.provision(INSTALLATION_SINGLETON_ID, dto.name));

    try {
      // `DatabaseProvisioningService.provision()` runs migrations against
      // `databaseName` — it does NOT create the physical Postgres database
      // itself (confirmed directly: neither the service nor
      // `runMigrationsForDatabase` issues a `CREATE DATABASE`). Every
      // existing real-PG caller (`database-provisioning.service.spec.ts`,
      // `two-company-real-pg-harness.ts`) creates it first — this is that
      // same, already-established step, not a new one invented here.
      const result = await this.databaseProvisioning.provision({
        companyId: company.id,
        host: this.config.database.host,
        port: this.config.database.port,
        databaseName,
        username: this.config.database.username,
        password: this.config.database.password,
        appRoot: this.config.releaseExecution.appRoot,
        tags: dto.tags,
        roleModuleCodes: dto.roleModuleCodes ?? [],
        initialAdminUserId: dto.initialAdminUserId,
      });
      const ready = await this.companyRegistry.findById(company.id);
      return {
        success: true,
        data: {
          company: await this.toView(ready!),
          migratedTags: result.migratedNames,
          roleSeedResult: result.roleSeedResult,
          entitlementApplied: result.entitlementApplied,
          initialAdminMembershipId: result.initialAdmin.id,
        },
      };
    } catch (err) {
      if (err instanceof ProvisioningFailedError) {
        throw new UnprocessableEntityException({
          message: `Company provisioning failed at stage "${err.stage}".`,
          stage: err.stage,
          detail: err.message,
          companyId: company.id,
        });
      }
      if (err instanceof Error && /not found/i.test(err.message) && /user/i.test(err.message)) {
        throw new BadRequestException(`initialAdminUserId does not reference an existing User: ${dto.initialAdminUserId}`);
      }
      throw err;
    }
  }

  @RequirePlatform('platform.company.suspend', 'editable')
  @Post(':id/suspend')
  async suspend(@Param('id') id: string) {
    return { success: true, data: await this.transition(id, () => this.companyActivation.suspend(id)) };
  }

  @RequirePlatform('platform.company.reactivate', 'editable')
  @Post(':id/reactivate')
  async reactivate(@Param('id') id: string) {
    return { success: true, data: await this.transition(id, () => this.companyActivation.reactivate(id)) };
  }

  @RequirePlatform('platform.company.decommission', 'editable')
  @Post(':id/decommission')
  async decommission(@Param('id') id: string) {
    return { success: true, data: await this.transition(id, () => this.companyActivation.decommission(id)) };
  }

  private async transition(id: string, fn: () => Promise<Company>): Promise<CompanyView> {
    try {
      const company = await fn();
      return this.toView(company);
    } catch (err) {
      if (err instanceof InvalidCompanyTransitionError) {
        throw new UnprocessableEntityException(err.message);
      }
      if (err instanceof Error && /not found/i.test(err.message)) {
        throw new NotFoundException(`Company not found: ${id}`);
      }
      throw err;
    }
  }

  private async toView(company: Company): Promise<CompanyView> {
    const registry = await this.databaseRegistry.findByCompanyId(company.id);
    return {
      id: company.id,
      name: company.name,
      status: company.status,
      createdAt: company.createdAt,
      databaseStatus: registry?.status ?? null,
    };
  }
}

import 'reflect-metadata';
import { Reflector } from '@nestjs/core';
import { PATH_METADATA, METHOD_METADATA } from '@nestjs/common/constants';
import { RequestMethod } from '@nestjs/common';
import { PERMISSION_METADATA_KEY, RequiredPermission } from '../permission/require-permission.decorator';
import { CompanyUsersController } from './company-users.controller';
import { CompanyInvitationsPublicController } from './company-invitations-public.controller';
import { InstallationMembershipController } from './installation-membership.controller';
import { COMPANY_MEMBERS_MANAGE_NODE } from './company-role-seeding';
import { CompanyRolesController } from './company-roles.controller';
import { COMPANY_ROLES_MANAGE_NODE } from '../permission/company-nodes';

/**
 * F2 wiring guard (the class-level metadata incident documented in `permission.guard.ts` is exactly the kind of regression this prevents):
 *  - every Company Users route is gated by the members-manage node; reads are read-only, every write is editable;
 *  - the Company plane exposes NO route that attaches an existing identity to a Company by a raw user id (the removed pre-F2 `POST /memberships`);
 *  - the public invitation routes exist only under `/invitations` and the only authenticated one carries the JWT guard.
 */
describe('F2 controller wiring', () => {
  const reflector = new Reflector();
  const routes = (ctrl: Function) =>
    Object.getOwnPropertyNames(ctrl.prototype)
      .filter((n) => n !== 'constructor' && typeof (ctrl.prototype as Record<string, unknown>)[n] === 'function' && Reflect.getMetadata(PATH_METADATA, (ctrl.prototype as Record<string, unknown>)[n] as object) !== undefined)
      .map((n) => {
        const handler = (ctrl.prototype as Record<string, unknown>)[n] as object;
        const required = reflector.getAllAndOverride<RequiredPermission>(PERMISSION_METADATA_KEY, [handler as Function, ctrl]);
        return { name: n, method: RequestMethod[Reflect.getMetadata(METHOD_METADATA, handler)], path: Reflect.getMetadata(PATH_METADATA, handler) as string, required };
      });

  it('every /company/users route requires core.company.members.manage; GET = read-only, POST/PUT/PATCH/DELETE = editable', () => {
    const all = routes(CompanyUsersController);
    expect(Reflect.getMetadata(PATH_METADATA, CompanyUsersController)).toBe('company/users');
    expect(all.length).toBeGreaterThanOrEqual(8);
    for (const r of all) {
      expect(r.required?.nodeKey).toBe(COMPANY_MEMBERS_MANAGE_NODE);
      expect(r.required?.access).toBe(r.method === 'GET' ? 'read-only' : 'editable');
    }
  });

  it('there is no Company-plane route that grants membership by a client-supplied user id (no POST at the controller root, no :companyId param)', () => {
    const all = routes(CompanyUsersController);
    expect(all.some((r) => r.method === 'POST' && (r.path === '/' || r.path === ''))).toBe(false);
    expect(all.some((r) => /companyId/i.test(r.path))).toBe(false);
    expect(all.filter((r) => r.method === 'POST').map((r) => r.path)).toEqual(['invitations']);
  });

  it('public invitation routes: preview (GET) and register (POST) are token-only; accept (POST) is JWT-guarded', () => {
    const all = routes(CompanyInvitationsPublicController);
    expect(Reflect.getMetadata(PATH_METADATA, CompanyInvitationsPublicController)).toBe('invitations');
    expect(all.map((r) => `${r.method} ${r.path}`).sort()).toEqual(['GET preview', 'POST accept', 'POST register']);
    const guards = (name: string) => Reflect.getMetadata('__guards__', (CompanyInvitationsPublicController.prototype as unknown as Record<string, object>)[name]) ?? [];
    expect(guards('accept').length).toBe(1);
    expect(guards('preview').length).toBe(0);
    expect(guards('register').length).toBe(0);
  });

  it('the platform plane keeps its explicit installation route (admin-only, :companyId by design) for support / bootstrap', () => {
    expect(Reflect.getMetadata(PATH_METADATA, InstallationMembershipController)).toBe('installation/companies/:companyId/memberships');
  });

  it('F3: every /company/roles route requires core.company.roles.manage; GET = read-only, every write = editable; static routes precede :roleId', () => {
    const all = routes(CompanyRolesController);
    expect(Reflect.getMetadata(PATH_METADATA, CompanyRolesController)).toBe('company/roles');
    expect(all.length).toBeGreaterThanOrEqual(12);
    for (const r of all) {
      expect(r.required?.nodeKey).toBe(COMPANY_ROLES_MANAGE_NODE);
      expect(r.required?.access).toBe(r.method === 'GET' ? 'read-only' : 'editable');
    }
    expect(all.some((r) => /companyId/i.test(r.path))).toBe(false);
    const order = Object.getOwnPropertyNames(CompanyRolesController.prototype);
    expect(order.indexOf('catalog')).toBeLessThan(order.indexOf('detail')); // GET /catalog must not be captured by GET /:roleId
    expect(order.indexOf('templates')).toBeLessThan(order.indexOf('detail'));
    expect(order.indexOf('fromTemplate')).toBeLessThan(order.indexOf('clone'));
  });
});

import { PlatformGuard, RequirePlatform } from '../platform/platform.guard';
import { Body, Controller, Delete, Get, Param, Patch, Post, Req, UnauthorizedException, UseGuards } from '@nestjs/common';
import { IsString, MinLength } from 'class-validator';
import { JwtAuthGuard, AuthenticatedRequest } from '../authentication/jwt-auth.guard';
import { RolesGuard } from '../authorization/roles.guard';
import { RequireRole } from '../authorization/require-role.decorator';
import { CompanyMembershipProvisioningService } from './company-membership-provisioning.service';
import { MembershipService } from './membership.service';

class GrantMembershipDto {
  @IsString()
  userId!: string;

  @IsString()
  @MinLength(1)
  roleKey!: string;
}

class ChangeMembershipRoleDto {
  @IsString()
  @MinLength(1)
  roleKey!: string;
}

/**
 * Membership HTTP Management (2026-09-24, D2). The SEPARATE
 * Installation-level administrative path — gated by the PLATFORM `admin`
 * role via the existing `RolesGuard` (the same guard/role
 * `AdminController` already uses), never by `CompanyContextGuard`. This is
 * deliberate, not a bypass of the Company authorization boundary: a
 * platform admin is trusted to name any Company explicitly (hence
 * `:companyId` as a real route param here, unlike the Company-scoped
 * controller), for control-plane/provisioning purposes — Area 6's Model B
 * boundary (Company-scoped `RolesGuard`/`PermissionGuard` reading
 * `req.companyContext`) is entirely untouched by this controller's
 * existence, since it never sets or reads `companyContext` at all.
 */
@Controller('installation/companies/:companyId/memberships')
@UseGuards(JwtAuthGuard, PlatformGuard)
export class InstallationMembershipController {
  constructor(
    private readonly provisioning: CompanyMembershipProvisioningService,
    private readonly memberships: MembershipService,
  ) {}

  @RequirePlatform('platform.membership.view')
  @Get()
  async list(@Param('companyId') companyId: string) {
    const rows = await this.memberships.findByCompany(companyId);
    return { success: true, data: rows };
  }

  @RequirePlatform('platform.membership.grant', 'editable')
  @Post()
  async grant(@Req() req: AuthenticatedRequest, @Param('companyId') companyId: string, @Body() dto: GrantMembershipDto) {
    if (!req.user) throw new UnauthorizedException();
    const membership = await this.provisioning.grantMembership(req.user.id, dto.userId, companyId, dto.roleKey);
    return { success: true, data: membership };
  }

  @RequirePlatform('platform.membership.revoke', 'editable')
  @Delete(':userId')
  async revoke(@Req() req: AuthenticatedRequest, @Param('companyId') companyId: string, @Param('userId') userId: string) {
    if (!req.user) throw new UnauthorizedException();
    await this.provisioning.revokeMembership(req.user.id, userId, companyId);
    return { success: true, data: { revoked: true } };
  }

  @RequirePlatform('platform.membership.update', 'editable')
  @Patch(':userId')
  async changeRole(@Req() req: AuthenticatedRequest, @Param('companyId') companyId: string, @Param('userId') userId: string, @Body() dto: ChangeMembershipRoleDto) {
    if (!req.user) throw new UnauthorizedException();
    const membership = await this.provisioning.changeMembershipRole(req.user.id, userId, companyId, dto.roleKey);
    return { success: true, data: membership };
  }
}

import { PlatformGuard, RequirePlatform } from '../platform/platform.guard';
import { Body, Controller, Delete, Get, Param, Put, Query, Req, UseGuards } from '@nestjs/common';
import { IsDefined, IsIn, IsOptional, IsString } from 'class-validator';
import { ConfigurationEngineService } from './configuration-engine.service';
import { ConfigScopeLevel } from './config-key.entity';
import { JwtAuthGuard, AuthenticatedRequest } from '../authentication/jwt-auth.guard';
import { RolesGuard } from '../authorization/roles.guard';
import { PermissionGuard } from '../permission/permission.guard';
import { RequirePermission } from '../permission/require-permission.decorator';

const CUSTOMER_SCOPES = ['installation', 'user', 'org'] as const;

class SetValueDto {
  @IsIn(CUSTOMER_SCOPES as unknown as string[])
  scope_type!: (typeof CUSTOMER_SCOPES)[number];

  @IsOptional()
  @IsString()
  scope_id?: string;

  /**
   * Correctness fix (2026-09-17, surfaced by the ADR-048 Procurement E2E
   * verification gate): this property had NO validation decorator, so
   * under the global pipe's `whitelist: true` + `forbidNonWhitelisted:
   * true` (main.ts), class-validator never recognized it as declared —
   * every `PUT /config/values/:key` call was stripped of its own `value`
   * and then rejected outright ("property value should not exist") for
   * EVERY caller, on every key, since this DTO was written. `@IsDefined`
   * only asserts presence (never `undefined`) — it imposes no type
   * constraint, preserving the original intent ("validated by the engine
   * against the key's type/range, accept unknown here").
   */
  @IsDefined()
  value!: unknown;
}

/**
 * Runtime Configuration Engine — ERP Foundation P2. Admin API.
 * `core.config.view` / `core.config.edit` are `core.*` permission nodes,
 * resolved by the Permission Engine's ancestor walk exactly like
 * `system.release.*`. The migration grants `admin` 'editable' at `core.config`.
 *
 * Daii-only scopes ('edition', 'platform') are NOT settable through this
 * customer-facing controller — they come from the Edition catalog (P3) / a
 * platform-operator path.
 */
@Controller('config')
@UseGuards(JwtAuthGuard, RolesGuard)
export class ConfigurationController {
  constructor(private readonly config: ConfigurationEngineService) {}

  @Get('keys')
  @UseGuards(PlatformGuard)
  @RequirePlatform('platform.config.view', 'read-only', { legacyNodes: ['core.config.view'] })
  listKeys(@Req() req: AuthenticatedRequest, @Query('module') moduleCode?: string) {
    return this.config.keys(moduleCode).map((meta) => ({
      key: meta.key,
      ownerModule: meta.ownerModule,
      valueType: meta.valueType,
      allowed: meta.allowed,
      scopeLevels: meta.scopeLevels,
      platformLocked: meta.platformLocked,
      securitySensitive: meta.securitySensitive,
      isFeatureFlag: meta.isFeatureFlag,
      titleCode: meta.titleCode,
      description: meta.description,
      writableLevels: this.config.writableLevels(meta.key),
      current: this.config.inspect(meta.key, { userId: req.user.id }),
    }));
  }

  @Get('keys/:key')
  @UseGuards(PlatformGuard)
  @RequirePlatform('platform.config.view', 'read-only', { legacyNodes: ['core.config.view'] })
  getKey(@Req() req: AuthenticatedRequest, @Param('key') key: string) {
    const meta = this.config.describe(key);
    return {
      key: meta.key,
      valueType: meta.valueType,
      allowed: meta.allowed,
      scopeLevels: meta.scopeLevels,
      platformLocked: meta.platformLocked,
      writableLevels: this.config.writableLevels(key),
      resolved: this.config.inspect(key, { userId: req.user.id }),
    };
  }

  @Put('values/:key')
  @UseGuards(PlatformGuard)
  @RequirePlatform('platform.config.edit', 'editable', { legacyNodes: ['core.config.edit'] })
  async setValue(@Req() req: AuthenticatedRequest, @Param('key') key: string, @Body() dto: SetValueDto) {
    await this.config.set(
      key,
      { scope_type: dto.scope_type as ConfigScopeLevel, scope_id: dto.scope_id ?? null },
      dto.value,
      { userId: req.user.id },
    );
    return { ok: true, resolved: this.config.inspect(key, { userId: req.user.id }) };
  }

  @Delete('values/:key')
  @UseGuards(PlatformGuard)
  @RequirePlatform('platform.config.edit', 'editable', { legacyNodes: ['core.config.edit'] })
  async clearValue(
    @Req() req: AuthenticatedRequest,
    @Param('key') key: string,
    @Query('scope_type') scopeType: ConfigScopeLevel,
    @Query('scope_id') scopeId?: string,
  ) {
    await this.config.clear(key, { scope_type: scopeType, scope_id: scopeId ?? null }, { userId: req.user.id });
    return { ok: true, resolved: this.config.inspect(key, { userId: req.user.id }) };
  }
}

