/**
 * Shared support for the business-test program (T-01…T-12). Test infrastructure only — no product code.
 * Every run: fresh disposable databases (harness) → approved-instance identity check → test → evidence written and hash-verified
 * BEFORE cleanup → teardown of exactly those databases → proof that no other database changed.
 */
export const FINGERPRINT_TABLES = [
  'stock_movements', 'stock_reservations', 'inventory_valuation_state', 'inventory_valuation_movements', 'accounting_financial_events',
  'accounting_journal_entries', 'accounting_journal_lines', 'event_outbox', 'customer_ledger_entries', 'supplier_ledger_entries',
  'treasury_transactions', 'customer_payments', 'supplier_payments', 'warehouse_transactions', 'warehouse_transaction_lines',
  'process_instances', 'process_transition_records', 'idempotency_records',
];
export const COMPANY_TAGS = ['sales', 'inventory', 'finance', 'procurement', 'accounting'];

export type Status = 'PASS' | 'FAIL' | 'FAIL-DEFECT' | 'BLOCKED' | 'STOP';
export interface CaseResult { id: string; status: Status; note?: string; data?: unknown }

export interface BizEnv {
  testId: string;
  prefix: string;
  h: TwoCompanyHarness;
  dsA: DataSource;
  manager: EntityManager;
  actor: string;
  inventory: InventoryService;
  whTx: WarehouseTransactionsService;
  processEngine: ProcessEngineService;
  audit: AuditService;
  run: any;
  systemIdentifier: string;
  dbNamesBefore: Array<{ datname: string; oid: string }>;
  databases: string[];
  results: CaseResult[];
  extraDataSources: DataSource[];
  finished?: boolean;
}

export async function adminDs(): Promise<DataSource> {
  const ds = new DataSource({
    type: 'postgres', host: process.env.DB_HOST, port: Number(process.env.DB_PORT), username: process.env.DB_USER, password: process.env.DB_PASSWORD,
    database: 'postgres', synchronize: false, logging: false,
  });
  await ds.initialize();
  return ds;
}

async function listDatabases(): Promise<Array<{ datname: string; oid: string }>> {
  const a = await adminDs();
  try {
    return await a.query('SELECT datname, oid::text AS oid FROM pg_database ORDER BY datname');
  } finally {
    await a.destroy();
  }
}

/** Seeds the admin user/role a workflow action needs plus a warehouse; returns ids. */
export async function seedBase(ds: DataSource, actor: string, code: string): Promise<{ warehouseId: string }> {
  await ds.query(`INSERT INTO "users" ("id","fullName","email") VALUES ($1,$2,$3) ON CONFLICT DO NOTHING`, [actor, 'Biz Test Admin', `biz-admin-${actor}@test.local`]);
  await ds.query(`INSERT INTO "roles" ("id","key") VALUES ($1,'admin') ON CONFLICT DO NOTHING`, [randomUUID()]);
  const role: Array<{ id: string }> = await ds.query(`SELECT id FROM "roles" WHERE "key" = 'admin'`);
  await ds.query(`INSERT INTO "user_roles" ("id","userId","roleId") VALUES ($1,$2,$3) ON CONFLICT DO NOTHING`, [randomUUID(), actor, role[0].id]);
  const warehouseId = randomUUID();
  await ds.query(`INSERT INTO "warehouses" ("id","code","name","status","kind") VALUES ($1,$2,$3,'active','main')`, [warehouseId, `WH-${code}`, `${code} Warehouse`]);
  return { warehouseId };
}

export async function seedWarehouse(ds: DataSource, code: string): Promise<string> {
  const id = randomUUID();
  await ds.query(`INSERT INTO "warehouses" ("id","code","name","status","kind") VALUES ($1,$2,$3,'active','main')`, [id, `WH-${code}`, `${code} Warehouse`]);
  return id;
}

export async function seedProduct(ds: DataSource, sku: string): Promise<string> {
  const id = randomUUID();
  await ds.query(`INSERT INTO "products" ("id","sku","name","unitPrice","status") VALUES ($1,$2,$3,'10.00','active')`, [id, sku, `${sku} Product`]);
  return id;
}

export async function setUpBiz(testId: string, prefix: string, opts: { tags?: string[]; roleModuleCodes?: string[] } = {}): Promise<BizEnv & { warehouseId: string }> {
  const run = ev.createRun(testId);
  const policyEntry = guard.loadPolicy().approved[0];
  if (!policyEntry) throw new Error('STOP: no approved test-database entry (the DB guard would refuse anyway)');
  const admin = await adminDs();
  const systemIdentifier: string = await ev.readSystemIdentifier(admin);
  await admin.destroy();
  if (systemIdentifier !== policyEntry.expectedSystemIdentifier) {
    ev.writeHeader(run, { systemIdentifier, expectedSystemIdentifier: policyEntry.expectedSystemIdentifier });
    ev.writeResult(run, [{ id: 'identity', status: 'STOP', note: 'system_identifier differs from the approved entry' }]);
    ev.finalize(run);
    throw new Error(`STOP: unexpected PostgreSQL system_identifier ${systemIdentifier}`);
  }
  const dbNamesBefore = await listDatabases();
  const databases = ['control_plane', 'company_a', 'company_b'].map((s) => `daii_test_${prefix}_${s}`);
  for (const n of databases) if (dbNamesBefore.some((d) => d.datname === n)) throw new Error(`STOP: ${n} already exists (fresh databases only)`);

  const h = await setUpTwoCompanyHarness({ namePrefix: prefix, extraCompanyTags: opts.tags ?? COMPANY_TAGS, ...(opts.roleModuleCodes ? { roleModuleCodes: opts.roleModuleCodes } : {}) });
  const dsA = await h.connections.getDataSource(h.companyAId);
  const actor = randomUUID();
  const { warehouseId } = await seedBase(dsA, actor, 'A1');

  const inert = {} as never;
  const audit = new AuditService(h.controlPlane);
  const numbering = new NumberingService(h.controlPlane);
  const processEngine = new ProcessEngineService(h.controlPlane);
  const authorization = new AuthorizationService(dsA.getRepository(Role), dsA.getRepository(UserRole));
  const products = new ProductsService(h.controlPlane, audit, inert);
  const policyRegistry = new InventoryPostingPolicyRegistry();
  policyRegistry.bind({
    assertManualReceiptReason: async () => ({ glAccountCode: 'stub' }),
    listManualReceiptReasons: () => ['FOUND_STOCK'],
    assertSaleReturnPostable: async () => undefined,
    assertSupplierInvoicePostable: async () => undefined,
  });
  const eventsStub = { publish: async () => undefined } as never;
  const inventory = new InventoryService(h.controlPlane, audit, inert, new BomService(h.controlPlane, audit, products), numbering, eventsStub, undefined, policyRegistry);
  const whTx = new WarehouseTransactionsService(h.controlPlane, numbering, processEngine, authorization, audit, products, inventory, policyRegistry);

  ev.writeHeader(run, { systemIdentifier, databases, prefix, tags: { controlPlane: ['core'], company: ['core', ...(opts.tags ?? COMPANY_TAGS)] } });
  ev.writeJson(run, 'databases-before.json', dbNamesBefore);
  return { testId, prefix, h, dsA, manager: dsA.manager, actor, inventory, whTx, processEngine, audit, run, systemIdentifier, dbNamesBefore, databases, results: [], extraDataSources: [], warehouseId };
}

/** A clone of the company DataSource with a larger pool so N concurrent calls really run on N connections. */
export async function widePool(env: BizEnv, max: number): Promise<DataSource> {
  const opts: any = env.dsA.options;
  const ds = new DataSource({ ...opts, extra: { ...(opts.extra ?? {}), max, application_name: `biz-${env.testId}` } });
  await ds.initialize();
  env.extraDataSources.push(ds);
  return ds;
}

export async function receive(env: BizEnv, warehouseId: string, productId: string, quantity: number, cost = '4.00'): Promise<string> {
  const txn = await env.whTx.createTransaction('receipt', warehouseId, null, [{ productId, quantity, unitCostBase: cost }], null, null, null, env.actor, undefined, env.manager, 'FOUND_STOCK');
  const state = await env.whTx.transition(txn.id, 'submit', env.actor, env.manager);
  if (state !== 'posted') throw new Error(`receipt did not post (state ${state})`);
  return txn.id;
}

/** issue/transfer document advanced to the `approved` state through the process engine — only the POSTING step remains. */
export async function approvedDoc(
  env: BizEnv, type: 'issue' | 'transfer' | 'adjustment', warehouseId: string, lines: Array<{ productId: string; quantity: number }>, destinationWarehouseId: string | null = null,
): Promise<string> {
  const txn = await env.whTx.createTransaction(type, warehouseId, destinationWarehouseId, lines, null, 'biz-test', null, env.actor, undefined, env.manager);
  await env.whTx.transition(txn.id, 'submit', env.actor, env.manager);
  await env.processEngine.transition(WAREHOUSE_TRANSACTION_PROCESS, 'warehouse_transaction', txn.id, 'approve', env.actor, env.manager);
  return txn.id;
}

export interface Outcome { ok: boolean; kind: string; message?: string; pgCode?: string; detail?: string }
export function classify(e: unknown): Outcome {
  const err = e as { constructor?: { name?: string }; message?: string; status?: number; getStatus?: () => number; driverError?: { code?: string; detail?: string; routine?: string } };
  const status = typeof err.getStatus === 'function' ? err.getStatus() : err.status;
  return { ok: false, kind: `${err.constructor?.name ?? 'Error'}${status ? `:${status}` : ''}`, message: String(err.message ?? '').slice(0, 200), pgCode: err.driverError?.code, detail: err.driverError?.detail ? String(err.driverError.detail).slice(0, 200) : undefined };
}
export async function attempt(fn: () => Promise<unknown>): Promise<Outcome> {
  try {
    await fn();
    return { ok: true, kind: 'OK' };
  } catch (e) {
    return classify(e);
  }
}
export const tally = (rs: Outcome[]) => rs.reduce<Record<string, number>>((m, r) => ({ ...m, [r.kind]: (m[r.kind] ?? 0) + 1 }), {});

export const fp = (env: BizEnv) => ev.fingerprint(env.dsA, FINGERPRINT_TABLES);
export const fpDiff = (a: Record<string, string>, b: Record<string, string>) => ev.diffFingerprints(a, b);
export const onHand = (env: BizEnv, wh: string, p: string) => env.inventory.getOnHand(wh, p, env.manager);
export const reserved = (env: BizEnv, wh: string, p: string) => env.inventory.getReserved(wh, p, env.manager);

export async function auditChainValid(env: BizEnv): Promise<boolean> {
  return (await env.audit.verifyCompanyChain(env.manager)).valid;
}

export async function negativeStockPairs(env: BizEnv): Promise<number> {
  const r = await env.dsA.query(`SELECT count(*)::int AS n FROM (SELECT 1 FROM stock_movements GROUP BY "warehouseId","productId" HAVING SUM(quantity) < 0) x`);
  return r[0].n;
}

export function record(env: BizEnv, name: string, data: unknown) { ev.writeJson(env.run, name, data); }
export function result(env: BizEnv, id: string, status: Status, note?: string, data?: unknown) { env.results.push({ id, status, note, data }); }

/**
 * Evidence first (written and hash-verified), then cleanup of exactly this run's databases, then proof that no other database changed.
 * Throws AFTER cleanup if any case is FAIL / STOP so jest reports the failure; BLOCKED / FAIL-DEFECT are reported in evidence without hiding them.
 */
export async function finishBiz(env: BizEnv): Promise<void> {
  env.finished = true;
  ev.writeResult(env.run, env.results);
  ev.finalize(env.run); // throws (=> STOP before cleanup) if evidence cannot be re-read with identical hashes
  for (const ds of env.extraDataSources) if (ds.isInitialized) await ds.destroy();
  await env.h.teardown();
  const after = await listDatabases();
  const gone = env.databases.every((n) => !after.some((d) => d.datname === n));
  const othersUnchanged = JSON.stringify(after) === JSON.stringify(env.dbNamesBefore);
  ev.writeJson(env.run, 'post-cleanup.json', { removed: env.databases, allRemoved: gone, otherDatabasesUnchanged: othersUnchanged, databasesAfter: after });
  ev.finalize(env.run);
  if (!gone || !othersUnchanged) throw new Error('STOP: cleanup did not leave the instance as found');
  const bad = env.results.filter((r) => r.status === 'FAIL' || r.status === 'STOP');
  if (bad.length) throw new Error(`cases failed: ${bad.map((b) => `${b.id}=${b.status}`).join(', ')}`);
}

/** Called from afterAll when a test threw before finishBiz: records what exists as STOP evidence, then removes this run's databases only. */
export async function abortBiz(env: BizEnv, reason: unknown): Promise<void> {
  if (env.finished) return;
  env.finished = true;
  try {
    env.results.push({ id: 'run-aborted', status: 'STOP', note: String((reason as Error)?.message ?? reason ?? 'test threw before completion').slice(0, 500) });
    ev.writeResult(env.run, env.results);
    ev.finalize(env.run);
  } finally {
    for (const ds of env.extraDataSources) if (ds.isInitialized) await ds.destroy();
    await env.h.teardown();
  }
}

/**
 * Audit-chain probe (an EXTRA check of this program, not a frozen T-xx criterion): verifies the Company audit hash chain and, when it is not valid,
 * preserves the non-secret facts needed to find the cause (position of the break, neighbouring rows, forks, gaps). A broken chain is reported as a
 * candidate defect (FAIL-DEFECT) with evidence — it never silently passes and it does not rewrite any frozen criterion.
 */
export async function auditProbe(env: BizEnv, label: string): Promise<boolean> {
  const verdict = await env.audit.verifyCompanyChain(env.manager);
  const q = (sql: string, p: unknown[] = []) => env.dsA.query(sql, p);
  const stats = (await q('SELECT count(*)::int AS n, min(seq)::int AS min, max(seq)::int AS max FROM audit_records'))[0];
  const detail: Record<string, unknown> = { label, valid: verdict.valid, brokenAtSeq: verdict.brokenAtSeq, ...stats };
  if (!verdict.valid) {
    const b = verdict.brokenAtSeq as number;
    detail.neighbours = await q(
      `SELECT seq, left("prevHash", 12) AS prev12, left(hash, 12) AS hash12, "timestamp"::text AS ts, action, resource, result FROM audit_records WHERE seq BETWEEN $1 AND $2 ORDER BY seq`, [b - 3, b + 3],
    );
    detail.forks = await q(`SELECT left("prevHash", 12) AS prev12, count(*)::int AS n, array_agg(seq ORDER BY seq) AS seqs FROM audit_records GROUP BY "prevHash" HAVING count(*) > 1 LIMIT 20`);
    detail.gaps = await q(`SELECT seq + 1 AS gap_after FROM (SELECT seq, lead(seq) OVER (ORDER BY seq) AS nxt FROM audit_records) x WHERE nxt IS NOT NULL AND nxt <> seq + 1 LIMIT 20`);
    detail.firstRecord = (await q(`SELECT seq, left("prevHash", 12) AS prev12, "timestamp"::text AS ts, action FROM audit_records ORDER BY seq LIMIT 1`))[0];
    detail.timestampColumn = (await q(`SELECT data_type FROM information_schema.columns WHERE table_name = 'audit_records' AND column_name = 'timestamp'`))[0];
  }
  record(env, `audit-chain-${label}.json`, detail);
  result(env, `audit-chain-${label}`, verdict.valid ? 'PASS' : 'FAIL-DEFECT', verdict.valid ? undefined : `candidate defect: audit hash chain invalid (first break at seq ${verdict.brokenAtSeq}) after ${label}`);
  return verdict.valid;
}

import { randomUUID } from 'crypto';
import { abortBiz, attempt, finishBiz, record, result, tally, widePool } from './biz-support';
import { FinEnv, setUpFinance } from './biz-finance-support';
import { CustomersService } from '../../domains/crm/application/customers.service';
import { AuthorizationService } from '../authorization/authorization.service';
import { Role } from '../authorization/role.entity';
import { UserRole } from '../authorization/user-role.entity';
import { NumberingService } from '../numbering/numbering.service';
import { ProcessDefinition } from '../process-engine/process-definition';

/**
 * PLAIN-MANAGER PROBES (informational — OUTSIDE the frozen T-xx set; they never change a frozen verdict; NO product code is changed by this file).
 * Question: do the two shared foundation primitives that use `manager ? run(manager) : dataSource.transaction(run)` keep their guarantees when a controller
 * hands them `req.companyContext.dataSource.manager` (a manager with NO open transaction)?
 *   N) NumberingService.getNextNumber — `SELECT … FOR UPDATE` then `UPDATE … SET lastNumber = <computed>`; with a plain manager the row lock is released at once.
 *   P) ProcessEngineService.transition — `SELECT … FOR UPDATE` then `UPDATE currentState`; same hazard.
 * Each is measured with (A) a plain manager and (B) the same call inside manager.transaction. Result is a measurement of the VERIFIED behaviour
 * (PASS = guarantee held, FAIL-DEFECT = guarantee violated), used to classify risk — not to demand a change.
 * Disposable databases `daii_test_biz_t17_*` only.
 */
describe('Plain-manager probes — numbering and process-engine', () => {
  jest.setTimeout(900_000);
  let env: FinEnv | undefined;
  let failure: unknown;
  afterAll(async () => {
    if (env) await abortBiz(env, failure);
  });

  it('records the behaviour of both primitives under concurrency', async () => {
    try {
      env = await setUpFinance('T-17', 'biz_t17');
      const e = env;
      const wide = await widePool(e, 40);
      const numbering = new NumberingService(e.h.controlPlane);
      await numbering.registerDocumentType('PROBE_PLAIN', 'PP', false, e.manager);
      await numbering.registerDocumentType('PROBE_TX', 'PT', false, e.manager);

      // ---- N) numbering ----
      const rounds = 10; const concurrent = 20;
      const dup = { plain: 0, transaction: 0 };
      const outcomes: Record<string, unknown[]> = { plain: [], transaction: [] };
      for (const style of ['plain', 'transaction'] as const) {
        const type = style === 'plain' ? 'PROBE_PLAIN' : 'PROBE_TX';
        for (let r = 0; r < rounds; r += 1) {
          const nums = await Promise.all(Array.from({ length: concurrent }, () => (style === 'plain'
            ? numbering.getNextNumber(type, wide.manager)
            : wide.manager.transaction((tx) => numbering.getNextNumber(type, tx))).then((n) => n, (err) => `ERR:${String(err?.message ?? err).slice(0, 40)}`)));
          const distinct = new Set(nums).size;
          if (distinct !== nums.length) dup[style] += 1;
          outcomes[style].push({ round: r, issued: nums.length, distinct });
        }
      }
      const finalPlain = (await e.dsA.query(`SELECT "lastNumber" FROM numbering_sequences WHERE "documentType" = 'PROBE_PLAIN'`))[0].lastNumber;
      const finalTx = (await e.dsA.query(`SELECT "lastNumber" FROM numbering_sequences WHERE "documentType" = 'PROBE_TX'`))[0].lastNumber;
      record(e, 'N-numbering.json', { rounds, concurrent, roundsWithDuplicateNumbers: dup, lastNumberAfter: { plain: finalPlain, transaction: finalTx }, expected: rounds * concurrent, outcomes });
      result(e, 'N-A-plain-manager', dup.plain === 0 && Number(finalPlain) === rounds * concurrent ? 'PASS' : 'FAIL-DEFECT', JSON.stringify({ roundsWithDuplicates: dup.plain, lastNumber: finalPlain, expected: rounds * concurrent }));
      result(e, 'N-B-transaction-manager', dup.transaction === 0 && Number(finalTx) === rounds * concurrent ? 'PASS' : 'FAIL-DEFECT', JSON.stringify({ roundsWithDuplicates: dup.transaction, lastNumber: finalTx, expected: rounds * concurrent }));

      // ---- P) process engine ----
      const def: ProcessDefinition = { key: 'probe_flow', initialState: 'a', transitions: [{ from: 'a', to: 'b', action: 'go' }, { from: 'b', to: 'c', action: 'go' }] };
      const prounds = 15; const pconc = 8;
      const pstats = { plain: { multiWin: 0, wins: [] as number[], extraHistory: 0 }, transaction: { multiWin: 0, wins: [] as number[], extraHistory: 0 } };
      for (const style of ['plain', 'transaction'] as const) {
        for (let r = 0; r < prounds; r += 1) {
          const id = randomUUID();
          await e.processEngine.start(def, 'probe', id, e.manager);
          const outs = await Promise.all(Array.from({ length: pconc }, () => attempt(() => (style === 'plain'
            ? e.processEngine.transition(def, 'probe', id, 'go', e.actor, wide.manager)
            : wide.manager.transaction((tx) => e.processEngine.transition(def, 'probe', id, 'go', e.actor, tx))))));
          const wins = outs.filter((o) => o.ok).length;
          const hist = (await e.dsA.query(`SELECT count(*)::int AS n FROM process_transition_records WHERE "processInstanceId" = (SELECT id FROM process_instances WHERE "definitionKey" = 'probe_flow' AND "entityId" = $1)`, [id]))[0].n;
          // from 'a' the legal path is a->b then b->c: a perfectly serialised run lets at most 2 of the identical 'go' requests succeed (a->b, b->c), the rest get 409
          pstats[style].wins.push(wins);
          if (wins > 2 || hist !== wins) pstats[style].multiWin += 1;
          void tally;
        }
      }
      record(e, 'P-process-engine.json', { prounds, pconc, pstats, note: 'serialised behaviour = at most 2 successes (a->b, b->c) and history rows = successes' });
      result(e, 'P-A-plain-manager', pstats.plain.multiWin === 0 ? 'PASS' : 'FAIL-DEFECT', JSON.stringify({ roundsViolating: pstats.plain.multiWin, wins: pstats.plain.wins }));
      result(e, 'P-B-transaction-manager', pstats.transaction.multiWin === 0 ? 'PASS' : 'FAIL-DEFECT', JSON.stringify({ roundsViolating: pstats.transaction.multiWin, wins: pstats.transaction.wins }));
      // ---- C) production call shape: CustomersService.createCustomer(dto, user, req.companyContext.dataSource.manager) — numbering is called with the caller's manager, the insert in a separate transaction ----
      const authz = new AuthorizationService(e.dsA.getRepository(Role), e.dsA.getRepository(UserRole));
      const limitsStub = { check: async () => ({ allowed: true, max: null }), consume: async () => ({ allowed: true, max: null }) } as never;
      const customers = new CustomersService(e.h.controlPlane, numbering, {} as never, e.audit, e.events, authz, {} as never, limitsStub);
      await numbering.registerDocumentType('customer', 'CUS', false, e.manager);
      const cstats = { plain: { ok: 0, errors: {} as Record<string, number>, distinctCodes: 0, rounds: 0 }, transaction: { ok: 0, errors: {} as Record<string, number>, distinctCodes: 0, rounds: 0 } };
      const crounds = 8; const cconc = 15;
      for (const style of ['plain', 'transaction'] as const) {
        for (let r = 0; r < crounds; r += 1) {
          const settled = await Promise.allSettled(Array.from({ length: cconc }, (_, i) => (style === 'plain'
            ? customers.createCustomer({ name: `probe-${style}-${r}-${i}` } as never, e.actor, wide.manager)
            : wide.manager.transaction((tx) => customers.createCustomer({ name: `probe-${style}-${r}-${i}` } as never, e.actor, tx)))));
          const codes = new Set<string>();
          for (const s of settled) {
            if (s.status === 'fulfilled') { cstats[style].ok += 1; codes.add((s.value as { code: string }).code); }
            else { const k = `${(s.reason as { code?: string; name?: string })?.code ?? (s.reason as Error)?.name ?? 'error'}`; cstats[style].errors[k] = (cstats[style].errors[k] ?? 0) + 1; }
          }
          cstats[style].distinctCodes += codes.size; cstats[style].rounds += 1;
        }
      }
      const expectedC = crounds * cconc;
      record(e, 'C-customer-create.json', { crounds, cconc, expectedPerStyle: expectedC, cstats });
      result(e, 'C-A-plain-manager', cstats.plain.ok === expectedC ? 'PASS' : 'FAIL-DEFECT', JSON.stringify({ succeeded: cstats.plain.ok, of: expectedC, errors: cstats.plain.errors }));
      result(e, 'C-B-transaction-manager', cstats.transaction.ok === expectedC ? 'PASS' : 'FAIL-DEFECT', JSON.stringify({ succeeded: cstats.transaction.ok, of: expectedC, errors: cstats.transaction.errors }));
      await finishBiz(e);
    } catch (err) {
      failure = err;
      throw err;
    }
  });
});

import { BizEnv, abortBiz, attempt, finishBiz, record, result, setUpBiz, tally, widePool } from './biz-support';
import { TreasuryService } from '../../domains/treasury/application/treasury.service';
import { AuditService } from '../audit/audit.service';
import { NumberingService } from '../numbering/numbering.service';
import { EventBusService } from '../events/event-bus.service';

/**
 * F-TRS-001 REPRODUCER (informational — OUTSIDE the frozen T-xx set; it never changes a frozen verdict).
 * Question: does TreasuryService keep a treasury account from being overdrawn by concurrent withdrawals when it is called with a plain
 * (non-transactional) EntityManager — which is how TreasuryController calls it (`req.companyContext.dataSource.manager`) — versus a transaction manager?
 *   A) plain manager (as the controller does)         -> overdraft occurrences over 15 rounds of 10 x 30.00 from 100.00
 *   B) wrapped in manager.transaction(tx => ...)      -> overdraft occurrences over 15 rounds
 * Disposable databases `daii_test_biz_t14_*` only. Uses the non-emitting cashOut (no accounting involved) so the balance logic is isolated.
 */
describe('F-TRS-001 reproducer — concurrent withdrawals, plain manager vs transaction manager', () => {
  jest.setTimeout(900_000);
  let env: (BizEnv & { warehouseId: string }) | undefined;
  let failure: unknown;
  afterAll(async () => {
    if (env) await abortBiz(env, failure);
  });

  it('records overdraft occurrences for both calling styles', async () => {
    try {
      env = await setUpBiz('T-14', 'biz_t14');
      const e = env;
      const wide = await widePool(e, 40);
      const inert = {} as never;
      const audit = new AuditService(e.h.controlPlane);
      const treasury = new TreasuryService(e.h.controlPlane, new NumberingService(e.h.controlPlane), audit, inert, new EventBusService(inert, e.h.connections));
      const type = (await treasury.listAccountTypes(e.manager)).find((t) => t.code === 'bank')!;
      const rounds = 15;
      const stats: Record<'plain' | 'transaction', { overdrafts: number; okCounts: number[]; balances: string[] }> = { plain: { overdrafts: 0, okCounts: [], balances: [] }, transaction: { overdrafts: 0, okCounts: [], balances: [] } };
      for (const style of ['plain', 'transaction'] as const) {
        for (let r = 1; r <= rounds; r += 1) {
          const acct = await treasury.createAccount(`F-TRS-${style}-${r}`, `F-TRS ${style} ${r}`, type.id, e.actor, e.manager);
