      await dsA.query(`INSERT INTO access_scopes (id, "userId", "orgUnitId", "includeDescendants", "createdBy") VALUES ($1,$2,$3,false,$4), ($5,$6,$7,false,$4)`, [randomUUID(), A1, u1, actor, randomUUID(), A2, u2]);
