            req.companyContext = { companyId: c.id, dataSource: c.ds };
            return true;
          },
        })
        .compile();
      app = moduleRef.createNestApplication();
      app.setGlobalPrefix('api');
      app.useGlobalPipes(new ValidationPipe({ whitelist: true, forbidNonWhitelisted: true, transform: true }));
      app.useGlobalFilters(new AllExceptionsFilter());
      await app.init();
      await app.listen(0, '127.0.0.1');
      const base = `http://127.0.0.1:${(app.getHttpServer().address() as { port: number }).port}/api`;

      // ---------- HTTP helpers ----------
      type Res = { status: number; ms: number; ok: boolean };
      const call = async (company: 'A' | 'B', method: string, path: string, body?: unknown, key?: string): Promise<Res> => {
        const t0 = performance.now();
        let status = 0;
        try {
          const r = await fetch(`${base}${path}`, { method, headers: { 'content-type': 'application/json', 'x-test-company': company, ...(key ? { 'idempotency-key': key } : {}) }, body: body === undefined ? undefined : JSON.stringify(body) });
          await r.arrayBuffer();
          status = r.status;
        } catch { status = -1; }
        return { status, ms: performance.now() - t0, ok: status >= 200 && status < 300 };
      };
      const pick = <T,>(a: T[]) => a[Math.floor(Math.random() * a.length)];
      const mix = PROFILE.mix as Array<{ op: string; weight: number }>;
      const totalW = mix.reduce((s, m) => s + m.weight, 0);
      const chooseOp = () => { let r = Math.random() * totalW; for (const m of mix) { if ((r -= m.weight) < 0) return m.op; } return mix[0].op; };

      const runOp = async (kind: 'distributed' | 'hot'): Promise<{ op: string; r: Res }> => {
        const op = chooseOp();
        const c = kind === 'hot' ? ctxs.A : ctxs[Math.random() < 0.5 ? 'A' : 'B'];
        const acct = kind === 'hot' ? c.accounts[0] : pick(c.accounts);
        const prod = kind === 'hot' ? c.products[0] : pick(c.products);
        const key = randomUUID();
        let r: Res;
        if (op === 'payment.on-account') {
          r = await call(c.company, 'POST', '/payments/on-account', { customerId: c.customerId, amount: '1.00', method: 'bank_transfer', treasuryAccountId: acct, reference: key.slice(0, 20) }, key);
          if (r.ok) { c.ledger.payments += 1; c.ledger.okByAccount[acct] = (c.ledger.okByAccount[acct] ?? 0) + 1; }
        } else if (op === 'inventory.receipt') {
          r = await call(c.company, 'POST', '/inventory/movements', { warehouseId: c.warehouseId, productId: prod, quantity: 1, movementType: 'receipt', unitCostBase: '4.00', reasonCode: 'FOUND_STOCK' });
          if (r.ok) { c.ledger.receipts += 1; c.ledger.receiptUnits += 1; }
        } else if (op === 'treasury.cash-in') {
          r = await call(c.company, 'POST', '/treasury/cash-in', { accountId: acct, amount: '1.00', reference: key.slice(0, 20) }, key);
          if (r.ok) { c.ledger.cashIn += 1; c.ledger.okByAccount[acct] = (c.ledger.okByAccount[acct] ?? 0) + 1; }
        } else if (op === 'treasury.cash-out') {
          r = await call(c.company, 'POST', '/treasury/cash-out', { accountId: acct, amount: '1.00', reference: key.slice(0, 20) }, key);
          if (r.ok) { c.ledger.cashOut += 1; c.ledger.okByAccount[acct] = (c.ledger.okByAccount[acct] ?? 0) - 1; }
        } else if (op === 'read.treasury-accounts') {
          r = await call(c.company, 'GET', '/treasury/accounts');
        } else {
          r = await call(c.company, 'GET', `/inventory/reports/movements?warehouseId=${c.warehouseId}`);
        }
        return { op, r };
      };

      // ---------- resource sampling ----------
      const samples: Array<Record<string, number>> = [];
      let prevCpu = cpus().map((c) => ({ ...c.times }));
      let prevProc = process.cpuUsage();
      let prevT = Date.now();
      let sampler: NodeJS.Timeout | undefined;
      let tick = 0;
      const sampleOnce = async () => {
        tick += 1;
        const now = cpus().map((c) => ({ ...c.times }));
        let idle = 0; let total = 0;
        now.forEach((t, i) => { const p = prevCpu[i]; const d = (t.user - p.user) + (t.nice - p.nice) + (t.sys - p.sys) + (t.irq - p.irq) + (t.idle - p.idle); total += d; idle += t.idle - p.idle; });
        prevCpu = now;
        const pu = process.cpuUsage(prevProc); prevProc = process.cpuUsage();
        const dt = (Date.now() - prevT) / 1000; prevT = Date.now();
        const row: Record<string, number> = { tSec: tick * 2, systemCpuPct: total ? Number((100 * (1 - idle / total)).toFixed(1)) : 0, nodeCpuPctOfOneCore: Number((100 * (pu.user + pu.system) / 1e6 / dt).toFixed(1)), nodeRssMB: Math.round(process.memoryUsage().rss / 2 ** 20) };
        if (tick % 3 === 0) {
          const r = spawnSync('powershell', ['-NoProfile', '-Command', "(Get-Process postgres -ErrorAction SilentlyContinue | Measure-Object WorkingSet64 -Sum).Sum"], { encoding: 'utf8', timeout: 5000 });
          row.postgresRssMB = Math.round(Number((r.stdout || '0').trim() || 0) / 2 ** 20);
        }
        try { row.dbConnections = (await dsA.query('SELECT count(*)::int AS n FROM pg_stat_activity'))[0].n; } catch { /* ignore */ }
        samples.push(row);
      };
      sampler = setInterval(() => { void sampleOnce(); }, 2000);

      // ---------- phases ----------
      const phaseResults: Array<Record<string, unknown>> = [];
      const wide = await widePool(e, 4); void wide;
      const runStep = async (phase: string, kind: 'distributed' | 'hot', users: number, seconds: number, windowSeconds?: number) => {
        const lat: Record<string, number[]> = {}; const status: Record<string, number> = {}; let okCount = 0; let total = 0;
        const windows: Array<{ t: number; p95: number; n: number }> = [];
        let cur: number[] = []; let winStart = Date.now();
        const end = Date.now() + seconds * 1000;
        const t0 = Date.now();
        const cpuStart = samples.length;
        const worker = async () => {
          while (Date.now() < end) {
            const { op, r } = await runOp(kind);
            total += 1; if (r.ok) okCount += 1;
            (lat[op] ??= []).push(r.ms); status[String(r.status)] = (status[String(r.status)] ?? 0) + 1;
            if (windowSeconds) { cur.push(r.ms); if (Date.now() - winStart >= windowSeconds * 1000) { cur.sort((a, b) => a - b); windows.push({ t: Math.round((Date.now() - t0) / 1000), p95: Math.round(pct(cur, 95)), n: cur.length }); cur = []; winStart = Date.now(); } }
          }
        };
        await Promise.all(Array.from({ length: users }, worker));
        const wall = (Date.now() - t0) / 1000;
        const all = Object.values(lat).flat().sort((a, b) => a - b);
        const perOp = Object.fromEntries(Object.entries(lat).map(([op, v]) => { v.sort((a, b) => a - b); return [op, { n: v.length, p50: Math.round(pct(v, 50)), p95: Math.round(pct(v, 95)), p99: Math.round(pct(v, 99)) }]; }));
        const slice = samples.slice(cpuStart);
        const maxOf = (k: string) => Math.max(0, ...slice.map((s) => s[k] ?? 0));
        const avgOf = (k: string) => { const v = slice.map((s) => s[k]).filter((x) => x !== undefined); return v.length ? Number((v.reduce((a, b) => a + b, 0) / v.length).toFixed(1)) : 0; };
        phaseResults.push({ phase, kind, virtualUsers: users, seconds: Number(wall.toFixed(1)), requests: total, success2xx: okCount, nonSuccess: total - okCount, statusCodes: status, requestsPerSec: Number((total / wall).toFixed(1)), p50: Math.round(pct(all, 50)), p95: Math.round(pct(all, 95)), p99: Math.round(pct(all, 99)), perOp, windows, resources: { systemCpuAvgPct: avgOf('systemCpuPct'), systemCpuMaxPct: maxOf('systemCpuPct'), nodeRssMaxMB: maxOf('nodeRssMB'), postgresRssMaxMB: maxOf('postgresRssMB'), dbConnectionsMax: maxOf('dbConnections') } });
      };
      for (const ph of PROFILE.phases as Array<{ name: string; kind: 'distributed' | 'hot'; virtualUsers: number[]; secondsEach: number; windowSeconds?: number }>) {
        for (const users of ph.virtualUsers) await runStep(ph.name, ph.kind, users, Math.max(3, Math.round(ph.secondsEach * SCALE)), ph.windowSeconds);
        await e.events.dispatchAfterCommit(dsA.manager); // keep the outbox from growing unbounded between phases (the app does this per request too)
      }
      clearInterval(sampler);

      // ---------- idempotency-at-HTTP probe: the same key sent 3x concurrently -> exactly one effect ----------
      const probeKeys = Array.from({ length: 15 }, () => randomUUID());
      const probeRes = await Promise.all(probeKeys.flatMap((k, i) => [0, 1, 2].map(() => (i % 2 === 0
        ? call('A', 'POST', '/payments/on-account', { customerId: ctxs.A.customerId, amount: '1.00', method: 'bank_transfer', treasuryAccountId: ctxs.A.accounts[2], reference: `idem-${i}` }, k)
        : call('A', 'POST', '/treasury/cash-in', { accountId: ctxs.A.accounts[3], amount: '1.00', reference: `idem-${i}` }, k)))));
      const probeOk = probeRes.filter((r) => r.ok).length;
      // each key => exactly one stored effect (payment or treasury leg) => count rows by reference
      const idemRows = (await dsA.query(`SELECT (SELECT count(*)::int FROM customer_payments WHERE reference LIKE 'idem-%') + (SELECT count(*)::int FROM treasury_transactions WHERE reference LIKE 'idem-%') AS n`))[0].n as number;
      ctxs.A.ledger.payments += probeKeys.filter((_, i) => i % 2 === 0).length; ctxs.A.ledger.okByAccount[ctxs.A.accounts[2]] = (ctxs.A.ledger.okByAccount[ctxs.A.accounts[2]] ?? 0) + probeKeys.filter((_, i) => i % 2 === 0).length;
      ctxs.A.ledger.cashIn += probeKeys.filter((_, i) => i % 2 === 1).length; ctxs.A.ledger.okByAccount[ctxs.A.accounts[3]] = (ctxs.A.ledger.okByAccount[ctxs.A.accounts[3]] ?? 0) + probeKeys.filter((_, i) => i % 2 === 1).length;
      const idemOk = idemRows === probeKeys.length;

      // ---------- drain the outbox completely, then the integrity oracle ----------
      let drained = 0;
      for (const ds of [dsA, dsB]) for (let i = 0; i < 2000; i += 1) { const d = await e.events.dispatchAfterCommit(ds.manager); drained += d.dispatched; if (d.dispatched === 0) break; }
      const oracle: Record<string, unknown> = { drainedEvents: drained, idempotencyProbe: { keys: probeKeys.length, httpOk: probeOk, storedEffects: idemRows, ok: idemOk } };
      let oracleOk = idemOk;
      for (const c of [ctxs.A, ctxs.B]) {
        const balErrors: string[] = [];
        for (const a of c.accounts) {
          const bal = Number(await e.treasury.getAccountBalance(a, c.ds.manager));
          const expected = FUND + (c.ledger.okByAccount[a] ?? 0);
          if (bal !== expected) balErrors.push(`${a.slice(0, 8)}: ${bal} != ${expected}`);
        }
        const payRows = (await c.ds.query(`SELECT count(*)::int AS n FROM customer_payments`))[0].n;
        const onHandUnits = Number((await c.ds.query(`SELECT coalesce(sum(quantity),0)::int AS n FROM stock_movements`))[0].n);
        const unpostedEvents = (await c.ds.query(`SELECT count(*)::int AS n FROM accounting_financial_events WHERE status <> 'POSTED'`))[0].n;
        const unbalanced = (await c.ds.query(`SELECT count(*)::int AS n FROM (SELECT "journalEntryId" FROM accounting_journal_lines GROUP BY 1 HAVING sum("debitBase") <> sum("creditBase")) x`))[0].n;
        const chain = await e.audit.verifyCompanyChain(c.ds.manager);
        const neg = (await c.ds.query(`SELECT count(*)::int AS n FROM (SELECT 1 FROM stock_movements GROUP BY "warehouseId","productId" HAVING sum(quantity) < 0) x`))[0].n;
        const ok = balErrors.length === 0 && payRows === c.ledger.payments && onHandUnits === c.ledger.receiptUnits && unpostedEvents === 0 && unbalanced === 0 && chain.valid && neg === 0;
        oracle[`company${c.company}`] = { balErrors, payRows, expectedPayments: c.ledger.payments, onHandUnits, expectedReceiptUnits: c.ledger.receiptUnits, unpostedEvents, unbalancedJournals: unbalanced, auditChainValid: chain.valid, negativeStockPairs: neg, ok };
        if (!ok) oracleOk = false;
      }
      const hardware = { cpuModel: cpus()[0]?.model, logicalCpus: cpus().length, totalMemGB: Number((totalmem() / 2 ** 30).toFixed(1)), node: process.version, profile: 'tools/testing/capacity-profile.json', scale: SCALE, note: 'load generator + application + PostgreSQL share one machine; fsync=off, autovacuum=off; local only' };
      record(e, 'T-16-capacity-http.json', { hardware, profile: PROFILE, phases: phaseResults, oracle });
      record(e, 'T-16-resource-samples.json', samples);
      result(e, 'T-16-integrity-oracle', oracleOk ? 'PASS' : 'FAIL-DEFECT', JSON.stringify(oracle).slice(0, 700));
      result(e, 'T-16-measurements-recorded', 'PASS', `phases=${phaseResults.length}; capacity NOT classified (targets unapproved)`);

      await auditProbe(e, 'final');
      await reconcileAndRecord(e, { nonGlTreasury: FUND * NACC, notes: [`${NACC} x ${FUND}.00 opening funding cash-ins are deliberately non-emitting (Company A); Company B verified by the oracle above`] });
      void COMPANY_TAGS; void negativeStockPairs;
      await finishBiz(e);
      expect(e.results.filter((r) => r.status === 'FAIL' || r.status === 'STOP')).toEqual([]);
    } catch (err) {
      failure = err;
      throw err;
    }
  });
});

import { randomUUID } from 'crypto';
import { BizEnv, abortBiz, finishBiz, record, result, seedProduct, setUpBiz, widePool } from './biz-support';
import { NumberingService } from '../numbering/numbering.service';
import { AuthorizationService } from '../authorization/authorization.service';
import { Role } from '../authorization/role.entity';
import { UserRole } from '../authorization/user-role.entity';
import { AuditService } from '../audit/audit.service';
import { CustomersService } from '../../domains/crm/application/customers.service';
import { SupplierService } from '../../domains/procurement/application/supplier.service';
import { PriceListsService } from '../../domains/commerce/application/price-lists.service';
import { ProductsService } from '../../domains/commerce/application/products.service';
import { SalesService } from '../../domains/sales/application/sales.service';

/**
 * T-19 — N-01 PER-ENDPOINT CONCURRENCY (regression test for the numbering/process-engine remediation; informational, outside the frozen T-xx set).
 * Each case drives the service method EXACTLY as its controller does — with `req.companyContext.dataSource.manager`, i.e. a plain manager with NO open
 * transaction — from many concurrent callers, and checks the user-visible guarantee: every request succeeds and receives a DISTINCT, persisted document code.
 * Paths covered (all call `NumberingService.getNextNumber(type, manager)`): customer create, supplier create, price-list create, sales-rep profile create.
 * Control: the same calls inside manager.transaction. Run BEFORE the fix these cases fail (duplicate numbers → unique violations / HTTP 500 / collision-skipping);
 * AFTER the fix they pass. Disposable databases `daii_test_biz_t19_*` only.
 */
describe('T-19 — concurrent creates through the numbering-based endpoints (plain manager, as controllers call them)', () => {
  jest.setTimeout(900_000);
  let env: (BizEnv & { warehouseId: string }) | undefined;
  let failure: unknown;
  afterAll(async () => {
    if (env) await abortBiz(env, failure);
  });

  it('every concurrent create succeeds with a distinct code', async () => {
    try {
      env = await setUpBiz('T-19', 'biz_t19');
      const e = env;
      const wide = await widePool(e, 40);
      const inert = {} as never;
      const audit = new AuditService(e.h.controlPlane);
      const numbering = new NumberingService(e.h.controlPlane);
      const authz = new AuthorizationService(e.dsA.getRepository(Role), e.dsA.getRepository(UserRole));
      const limitsStub = { check: async () => ({ allowed: true, max: null }), consume: async () => ({ allowed: true, max: null }) } as never;
      const customers = new CustomersService(e.h.controlPlane, numbering, inert, audit, inert, authz, inert, limitsStub);
      const suppliers = new SupplierService(e.h.controlPlane, audit, inert, numbering);
      const products = new ProductsService(e.h.controlPlane, audit, inert);
      const priceLists = new PriceListsService(e.h.controlPlane, numbering, audit, products, { publish: async () => undefined } as never);
      const sales = new SalesService(e.h.controlPlane, numbering, authz, audit);
      await numbering.registerDocumentType('customer', 'CUS', false, e.manager);
      await numbering.registerDocumentType('price_list', 'PL', false, e.manager);
      await numbering.registerDocumentType('sales_rep', 'SR', false, e.manager);
      await e.dsA.query(`INSERT INTO roles (id, key) VALUES ($1,'sales_rep') ON CONFLICT DO NOTHING`, [randomUUID()]);
      void seedProduct;

      const rounds = 8; const conc = 10;
      type Case = { name: string; table: string; codeColumn: string; call: (mgr: import('typeorm').EntityManager, tag: string) => Promise<unknown> };
      const cases: Case[] = [
        { name: 'customer.create', table: 'customers', codeColumn: 'code', call: (m, tag) => customers.createCustomer({ name: `c-${tag}` } as never, e.actor, m) },
        { name: 'supplier.create', table: 'suppliers', codeColumn: 'code', call: (m, tag) => suppliers.create({ legalName: `s-${tag}` } as never, e.actor, m) },
        { name: 'priceList.create', table: 'price_lists', codeColumn: 'code', call: (m, tag) => priceLists.createPriceList(`pl-${tag}`, e.actor, m) },
        {
          name: 'salesRep.create', table: 'sales_rep_profiles', codeColumn: '"salesCode"',
          call: async (m, tag) => {
            const uid = randomUUID();
            await e.dsA.query(`INSERT INTO users (id, "fullName", email) VALUES ($1,$2,$3)`, [uid, `rep-${tag}`, `rep-${tag}-${uid.slice(0, 6)}@t19.local`]);
            return sales.createSalesRepProfile(uid, null, e.actor, m);
          },
        },
      ];
      const summary: Record<string, unknown> = {};
      for (const c of cases) {
        for (const style of ['plain', 'transaction'] as const) {
          const errors: Record<string, number> = {};
          let ok = 0;
          for (let r = 0; r < rounds; r += 1) {
            const settled = await Promise.allSettled(Array.from({ length: conc }, (_, i) => {
              const tag = `${style}-${r}-${i}`;
              return style === 'plain' ? c.call(wide.manager, tag) : wide.manager.transaction((tx) => c.call(tx, tag));
            }));
            for (const s of settled) {
              if (s.status === 'fulfilled') ok += 1;
              else { const k = String((s.reason as { code?: string; name?: string })?.code ?? (s.reason as Error)?.name ?? 'error'); errors[k] = (errors[k] ?? 0) + 1; }
            }
          }
          const expected = rounds * conc;
          const stored = (await e.dsA.query(`SELECT count(*)::int AS n, count(DISTINCT ${c.codeColumn})::int AS d FROM ${c.table} WHERE ${c.codeColumn} IS NOT NULL`))[0] as { n: number; d: number };
          summary[`${c.name}/${style}`] = { expected, succeeded: ok, errors, storedRows: stored.n, distinctCodes: stored.d };
          const good = ok === expected && Object.keys(errors).length === 0;
          result(e, `T-19-${c.name}-${style}`, good ? 'PASS' : 'FAIL-DEFECT', JSON.stringify({ succeeded: ok, expected, errors }));
        }
        // distinctness over everything this endpoint stored (plain + transaction runs share one table)
        const dd = (await e.dsA.query(`SELECT count(*)::int AS n, count(DISTINCT ${c.codeColumn})::int AS d FROM ${c.table} WHERE ${c.codeColumn} IS NOT NULL`))[0] as { n: number; d: number };
        result(e, `T-19-${c.name}-codes-distinct`, dd.n === dd.d ? 'PASS' : 'FAIL-DEFECT', JSON.stringify(dd));
      }
      record(e, 'T-19-summary.json', { rounds, conc, summary });
      await finishBiz(e);
    } catch (err) {
      failure = err;
      throw err;
    }
  });
});

import { DataSource } from 'typeorm';
import { BizEnv, abortBiz, finishBiz, record, result, setUpBiz } from './biz-support';
import { COMPANY_ENTITY_REGISTRY } from '../database-registry/company-entity-registry';

/**
 * TEST-03 / axis 2 — READ-ONLY schema-drift check (no product code is changed; the database is a disposable `daii_test_biz_t18_*`).
 * A fresh Company database is migrated with EVERY Company tag (the same migrations a new Company receives), then TypeORM's schema builder is asked — without executing
 * anything (`log()`) — which statements would be needed to make the database match the entity metadata (COMPANY_ENTITY_REGISTRY). Any statement returned is a drift between
 * the entities the code expects and what the migrations create (the class of defect seen earlier with `roles.type`). The reverse direction (tables/columns that exist in the
 * database but no entity maps) is reported too. Both lists are recorded as evidence; non-empty lists are FINDINGS (FAIL-DEFECT), not harness errors.
 */
describe('TEST-03 — entity metadata vs migrated Company schema', () => {
  jest.setTimeout(900_000);
  let env: (BizEnv & { warehouseId: string }) | undefined;
  let failure: unknown;
  afterAll(async () => {
    if (env) await abortBiz(env, failure);
  });

  it('reports drift in both directions', async () => {
    try {
      const ALL_TAGS = ['sales', 'inventory', 'finance', 'procurement', 'accounting', 'logistics', 'manufacturing', 'hr', 'attendance', 'commission', 'payroll', 'targets'];
      env = await setUpBiz('T-18', 'biz_t18', { tags: ALL_TAGS });
      const e = env;
      const dbName = e.databases.find((d) => d.endsWith('_company_a'))!;
      const o: any = e.dsA.options;
      const ds = new DataSource({ type: 'postgres', host: o.host, port: o.port, username: o.username, password: o.password, database: dbName, entities: COMPANY_ENTITY_REGISTRY as never, synchronize: false, logging: false });
      await ds.initialize();
      try {
        // entity -> schema: what would the schema builder have to do?
        const sqlInMemory = await ds.driver.createSchemaBuilder().log();
        const statements = sqlInMemory.upQueries.map((q) => q.query.replace(/\s+/g, ' ').slice(0, 300));
        // schema -> entity: tables / columns present in the database with no entity mapping
        const mappedTables = new Set(ds.entityMetadatas.map((m) => m.tableName));
        const dbTables: Array<{ table_name: string }> = await ds.query(`SELECT table_name FROM information_schema.tables WHERE table_schema = 'public' AND table_type = 'BASE TABLE'`);
        const infra = new Set(['typeorm_migrations', 'migrations', 'schema_migrations']);
        const unmappedTables = dbTables.map((t) => t.table_name).filter((t) => !mappedTables.has(t) && !infra.has(t)).sort();
        const dbCols: Array<{ table_name: string; column_name: string }> = await ds.query(`SELECT table_name, column_name FROM information_schema.columns WHERE table_schema = 'public'`);
        const mappedCols = new Map(ds.entityMetadatas.map((m) => [m.tableName, new Set(m.columns.map((c) => c.databaseName))]));
        const unmappedColumns = dbCols.filter((c) => mappedCols.has(c.table_name) && !mappedCols.get(c.table_name)!.has(c.column_name)).map((c) => `${c.table_name}.${c.column_name}`).sort();
        record(e, 'T-18-schema-drift.json', { entityCount: ds.entityMetadatas.length, tablesInDatabase: dbTables.length, entityToSchemaStatements: statements, tablesWithoutEntity: unmappedTables, columnsWithoutEntityProperty: unmappedColumns });
        result(e, 'T-18-entity-to-schema', statements.length === 0 ? 'PASS' : 'FAIL-DEFECT', `${statements.length} statement(s) the schema builder would need; first: ${statements[0] ?? '-'}`);
        result(e, 'T-18-schema-to-entity-tables', unmappedTables.length === 0 ? 'PASS' : 'FAIL-DEFECT', `${unmappedTables.length} table(s) without an entity: ${unmappedTables.slice(0, 12).join(', ')}`);
        result(e, 'T-18-schema-to-entity-columns', unmappedColumns.length === 0 ? 'PASS' : 'FAIL-DEFECT', `${unmappedColumns.length} column(s) without an entity property: ${unmappedColumns.slice(0, 12).join(', ')}`);
      } finally {
        await ds.destroy();
      }
      // ---- control-plane database vs the platform entities (every *.entity.ts that is not a Company entity) ----
      const cpName = e.databases.find((d) => d.endsWith('_control_plane'))!;
      const company = new Set(COMPANY_ENTITY_REGISTRY as unknown[]);
      const cp = new DataSource({ type: 'postgres', host: o.host, port: o.port, username: o.username, password: o.password, database: cpName, entities: [process.cwd() + '/src/**/*.entity.ts'], synchronize: false, logging: false });
      await cp.initialize();
      try {
        const platformMeta = cp.entityMetadatas.filter((m) => !company.has(m.target));
        const cp2 = new DataSource({ type: 'postgres', host: o.host, port: o.port, username: o.username, password: o.password, database: cpName, entities: platformMeta.map((m) => m.target) as never, synchronize: false, logging: false });
        await cp2.initialize();
        try {
          const up = (await cp2.driver.createSchemaBuilder().log()).upQueries.map((q) => q.query.replace(/\s+/g, ' ').slice(0, 300));
          const structural = up.filter((q) => /ADD COLUMN|DROP COLUMN|CREATE TABLE|DROP TABLE|ALTER COLUMN/.test(q));
          record(e, 'T-18-control-plane-drift.json', { platformEntities: platformMeta.length, statements: up.length, structural, all: up });
          result(e, 'T-18-control-plane-structural', structural.length === 0 ? 'PASS' : 'FAIL-DEFECT', `${platformMeta.length} platform entities; ${up.length} statement(s), ${structural.length} structural: ${structural.slice(0, 6).join(' | ')}`);
        } finally { await cp2.destroy(); }
      } finally { await cp.destroy(); }
      await finishBiz(e);
    } catch (err) {
      failure = err;
      throw err;
    }
  });
});
